  border: 2px dashed #111111;
  background: rgba(0, 0, 0, 0.045);
  pointer-events: none;
  z-index: 9999;
  box-sizing: border-box;
}

/* מצב ציור - cursor crosshair */
.hotspot-drawing-mode {
  cursor: crosshair !important;
}
.hotspot-drawing-mode * {
