/* ===== דף כתבות ===== */
.articles-page { width: 100%; background: #f2f2f2; direction: rtl; padding: 0; box-sizing: border-box; font-family: -apple-system, 'Segoe UI', Arial, sans-serif; }
.art-inner { max-width: 1140px; margin: 0 auto; padding: 48px 18px 40px; box-sizing: border-box; }

/* Search */
.art-search-wrap { margin-bottom: 18px; }
.art-search { width: 100%; padding: 13px 18px; border: 1.5px solid #dddddd; border-radius: 10px; font-size: 15px; box-sizing: border-box; direction: rtl; background: #ffffff; transition: border-color 0.2s, box-shadow 0.2s; }
.art-search:focus { outline: none; border-color: #111111; box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.06); }
.art-no-results { text-align: center; color: #999999; font-size: 15px; padding: 30px 0; }

/* Featured grid */
.art-featured-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 28px; }
.art-featured-card { position: relative; overflow: hidden; height: 190px; border-radius: 12px; cursor: pointer; box-shadow: 0 3px 14px rgba(0, 0, 0, 0.12); transition: transform 0.2s, box-shadow 0.2s; }
.art-featured-card:hover { transform: translateY(-3px); box-shadow: 0 10px 32px rgba(0, 0, 0, 0.22); }
.art-featured-card img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.35s; }
.art-featured-card:hover img { transform: scale(1.05); }
.art-featured-overlay { position: absolute; inset: 0; background: linear-gradient(to top, rgba(0, 0, 0, 0.85) 0%, rgba(0, 0, 0, 0.1) 55%, transparent 100%); }
.art-featured-info { position: absolute; bottom: 0; right: 0; left: 0; padding: 18px 14px 12px; color: #262626; }
.art-featured-info h3 { margin: 6px 0 0; font-size: 14px; font-weight: 800; line-height: 1.35; text-shadow: 0 1px 5px rgba(0, 0, 0, 0.5); }
.art-featured-meta { font-size: 10px; color: rgba(38, 38, 38, 0.7); margin-top: 5px; }

/* Shared */
.art-category-badge { display: inline-block; padding: 2px 9px; border-radius: 4px; font-size: 10px; font-weight: 700; color: #ffffff !important; letter-spacing: 0.3px; background: #111111 !important; }
.art-meta { display: flex; flex-direction: row; gap: 7px; font-size: 11px; color: #999999; margin-bottom: 6px; align-items: center; flex-wrap: wrap; }
.art-section-title { font-size: 16px; font-weight: 800; color: #111111; padding-bottom: 10px; margin-bottom: 14px; border-bottom: 3px solid #111111; display: inline-block; }

/* Layout - 3 עמודות בסגנון Reddit (סרגל ימין, תוכן מרכזי, סרגל שמאל sticky) */
.art-layout { display: flex; flex-direction: row; gap: 24px; align-items: flex-start; justify-content: space-between; width: 100%; }
.art-main { flex: 1; min-width: 0; order: 0 !important; }
.art-layout .art-sidebar-right { order: -1 !important; width: 270px; flex-shrink: 0; position: sticky; top: 76px; }
.art-layout .art-sidebar-left { order: 1 !important; width: 270px; flex-shrink: 0; position: sticky; top: 76px; }
.art-sidebar { width: 270px; flex-shrink: 0; display: flex; flex-direction: column; gap: 16px; box-sizing: border-box; }

/* Article rows (full width list) */
.art-rows { background: #ffffff; border-radius: 12px; padding: 4px 22px; box-shadow: 0 1px 6px rgba(0, 0, 0, 0.07); }
.art-row { display: flex; flex-direction: row; align-items: center; gap: 20px; padding: 22px 0; border-bottom: 1px solid #eeeeee; cursor: pointer; transition: opacity 0.15s; }
.art-row:last-child { border-bottom: none; }
.art-row:hover .art-row-text h3 { color: #111111; }
.art-row-text { flex: 1; min-width: 0; }
.art-row-text h3 { font-size: 17px; font-weight: 800; margin: 0 0 12px; line-height: 1.45; color: #111111; transition: color 0.15s; }
.art-row-text p { font-size: 13px; color: #777777; margin: 0 0 12px; line-height: 1.6; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.art-row-meta { display: flex; gap: 8px; font-size: 12px; color: #111111; font-weight: 600; align-items: center; }
.art-row-meta .art-row-sep { color: #cccccc; }
.art-row-img-wrap { position: relative; width: 170px; height: 110px; flex-shrink: 0; border-radius: 8px; overflow: hidden; background: #000000; }
.art-row-img-wrap::before { content: ""; position: absolute; inset: 0; background-image: var(--bg-img); background-size: cover; background-position: center; filter: blur(10px) brightness(0.6); transform: scale(1.15); pointer-events: none; }
.art-row-img-wrap img { position: relative; width: 100%; height: 100%; object-fit: contain; display: block; border-radius: 8px; z-index: 1; }
.art-row-img-placeholder {
