  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}
.art-row-img-placeholder::after {
  content: attr(data-icon);
  font-size: 32px;
  opacity: 0.35;
}

/* ===== קרוסלת תמונות בכרטיס גלריה: חיצי ניווט על התמונה + מונה + החלקת אצבע ===== */
