/* ===== עמוד חנות ===== */
.shop-page { width: 100%; background: #f5f5f7; direction: rtl; box-sizing: border-box; font-family: -apple-system, 'Segoe UI', Arial, sans-serif; }
.shop-inner { max-width: 1140px; margin: 0 auto; padding: 48px 18px 50px; box-sizing: border-box; }
.shop-header { text-align: center; margin-bottom: 36px; }
.shop-title { font-size: 34px; font-weight: 900; color: #111111; margin: 0 0 8px; }
.shop-subtitle { font-size: 17px; color: #888888; margin: 0; }
/* Search + layout */
.shop-search-wrap { max-width: 700px; margin: 0 auto 32px; }
.shop-search { width: 100%; padding: 13px 18px; border: 1.5px solid #dddddd; border-radius: 12px; font-size: 15px; box-sizing: border-box; direction: rtl; background: #ffffff; transition: border-color 0.2s, box-shadow 0.2s; }
.shop-search:focus { outline: none; border-color: #111111; box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.06); }
.shop-no-results { text-align: center; color: #999999; font-size: 15px; padding: 30px 0; }
.shop-layout { display: flex; flex-direction: row; gap: 26px; align-items: flex-start; }
.shop-main { flex: 1; min-width: 0; }
.shop-sidebar { width: 280px; flex-shrink: 0; }
.shop-sidebar-box { background: #ffffff; border-radius: 14px; padding: 20px; box-shadow: 0 1px 8px rgba(0, 0, 0, 0.06); }
.shop-sidebar-title { font-size: 16px; font-weight: 800; color: #111111; padding-bottom: 10px; margin-bottom: 12px; border-bottom: 3px solid #111111; }
.shop-best-item { display: flex; gap: 10px; padding: 12px 0; border-bottom: 1px solid #f0f0f0; align-items: center; transition: background 0.15s; border-radius: 6px; }
.shop-best-item:last-child { border-bottom: none; padding-bottom: 0; }
.shop-best-item:hover { background: #fafafa; }
.shop-best-num { font-size: 20px; font-weight: 900; color: #e5e5e5; min-width: 28px; text-align: center; }
.shop-best-img { width: 48px; height: 48px; object-fit: contain; flex-shrink: 0; }
.shop-best-text { flex: 1; min-width: 0; }
.shop-best-name { font-size: 13px; font-weight: 700; color: #111111; line-height: 1.35; }
.shop-best-price { font-size: 12px; color: #888888; margin-top: 3px; }
.shop-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 22px; }
.shop-card { position: relative; background: #ffffff; border-radius: 18px; padding: 30px 26px; display: flex; flex-direction: column; box-shadow: 0 1px 8px rgba(0, 0, 0, 0.06); transition: box-shadow 0.2s, transform 0.15s; }
.shop-card:hover { box-shadow: 0 10px 30px rgba(0, 0, 0, 0.12); transform: translateY(-3px); }
.shop-card-img { position: relative; width: 100%; height: 230px; display: flex; align-items: center; justify-content: center; margin-bottom: 22px; }
.shop-cart-btn { position: absolute; bottom: 0; left: 0; width: 52px; height: 52px; border-radius: 50%; background: #ffffff; border: 1px solid #eeeeee; box-shadow: 0 3px 12px rgba(0, 0, 0, 0.18); cursor: pointer; display: flex; align-items: center; justify-content: center; color: #111111; transition: transform 0.15s, background 0.15s; }
.shop-cart-btn svg { width: 22px; height: 22px; }
.shop-cart-btn .shop-cart-plus { position: absolute; top: 6px; right: 8px; font-size: 14px; font-weight: 900; line-height: 1; }
.shop-cart-btn:hover { transform: scale(1.08); background: #111111; color: #ffffff; }
/* Floating cart */
.shop-cart-fab { position: fixed; bottom: 26px; left: 26px; width: 60px; height: 60px; border-radius: 16px; background: #111111; color: #ffffff; border: none; cursor: pointer; box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3); display: flex; align-items: center; justify-content: center; z-index: 9000; transition: transform 0.15s; }
.shop-cart-fab svg { width: 26px; height: 26px; }
.shop-cart-fab.shop-cart-bump { transform: scale(1.2); }
.shop-cart-count { position: absolute; top: -4px; right: -4px; background: #e53935; color: #ffffff; min-width: 22px; height: 22px; border-radius: 11px; font-size: 12px; font-weight: 800; align-items: center; justify-content: center; padding: 0 5px; box-sizing: border-box; }
.shop-cart-panel { position: fixed; bottom: 96px; left: 26px; width: 330px; max-height: 70vh; background: #ffffff; border-radius: 16px; box-shadow: 0 12px 40px rgba(0, 0, 0, 0.25); z-index: 9001; flex-direction: column; direction: rtl; overflow: hidden; }
.shop-cart-header { display: flex; justify-content: space-between; align-items: center; padding: 16px 18px; border-bottom: 1px solid #eeeeee; font-weight: 800; font-size: 16px; }
.shop-cart-close { background: none; border: none; font-size: 16px; cursor: pointer; color: #888888; }
.shop-cart-items { overflow-y: auto; padding: 8px 14px; flex: 1; }
.shop-cart-empty { text-align: center; color: #999999; padding: 30px 0; font-size: 14px; }
.shop-cart-row { display: flex; align-items: center; gap: 10px; padding: 10px 0; border-bottom: 1px solid #f3f3f3; }
.shop-cart-row img { width: 44px; height: 44px; object-fit: contain; flex-shrink: 0; }
.shop-cart-row-text { flex: 1; min-width: 0; }
.shop-cart-row-name { font-size: 13px; font-weight: 700; color: #111111; line-height: 1.3; }
.shop-cart-row-price { font-size: 12px; color: #888888; margin-top: 3px; }
.shop-cart-remove { background: none; border: none; color: #cccccc; cursor: pointer; font-size: 14px; }
.shop-cart-remove:hover { color: #b91c1c; }
.shop-cart-footer { padding: 14px 18px; border-top: 1px solid #eeeeee; }
.shop-cart-total { font-size: 15px; font-weight: 800; color: #111111; margin-bottom: 10px; }
.shop-cart-checkout { width: 100%; background: #111111; color: #ffffff; border: none; border-radius: 8px; padding: 11px; font-size: 14px; font-weight: 800; cursor: pointer; }
.shop-cart-checkout:hover { background: #000000; }
.shop-card-img img { max-width: 100%; max-height: 100%; object-fit: contain; }
.shop-img-placeholder { width: 100%; height: 100%; background: #f0f0f0; border-radius: 12px; }
.shop-label { font-size: 13px; font-weight: 700; color: #111111; margin-bottom: 8px; }
.shop-name { font-size: 19px; font-weight: 700; color: #111111; margin: 0 0 14px; line-height: 1.35; }
.shop-price { font-size: 17px; color: #333333; font-weight: 500; margin-top: auto; }
.shop-add-btn { display: none; width: 100%; max-width: 360px; margin: 28px auto 0; border: 2px dashed #111111; background: #ffffff; color: #111111; padding: 14px; cursor: pointer; font-size: 15px; font-weight: 700; border-radius: 12px; box-sizing: border-box; transition: background 0.15s; }
.shop-add-btn:hover { background: #f0f0f0; }
.edit-mode .shop-add-btn { display: block; }
.shop-delete-btn { display: none; position: absolute; top: 12px; left: 12px; background: rgba(0, 0, 0, 0.6); border: none; border-radius: 50%; width: 30px; height: 30px; color: #ffffff; cursor: pointer; font-size: 15px; font-weight: 700; line-height: 1; align-items: center; justify-content: center; z-index: 2; }
.shop-delete-btn:hover { background: #b91c1c; }
.edit-mode .shop-delete-btn { display: flex; }
@media (max-width: 900px) {
  .shop-layout { flex-direction: column; }
  .shop-sidebar { width: 100%; }
}
@media (max-width: 768px) {
  .shop-inner { padding: 28px 12px 40px; }
  .shop-grid { grid-template-columns: 1fr; }
  .shop-title { font-size: 26px; }
  .shop-card-img { height: 200px; }
