/* ============================================================
   שכבת רענון עיצובי — מראה מודרני לעמודי התוכן
   (תמונות / סיפורים / כתבות / קורסים). שכבה תוספתית בלבד:
   נטענת אחרונה ודורסת את הכללים הישנים בלי לשנות מבנה HTML.
   ============================================================ */

.articles-page {
  --acc: #111827;
  --acc-soft: rgba(17, 24, 39, 0.08);
  --surface: #ffffff;
  --line: rgba(17, 17, 26, 0.08);
  --text: #0f1115;
  --muted: #6b7280;
  --r-lg: 16px;
  --r-md: 12px;
  --shadow-sm: 0 1px 2px rgba(16,24,40,0.04), 0 1px 3px rgba(16,24,40,0.06);
  --shadow-md: 0 2px 4px rgba(16,24,40,0.04), 0 12px 28px -14px rgba(16,24,40,0.20);
  --shadow-lg: 0 4px 8px rgba(16,24,40,0.05), 0 28px 52px -22px rgba(16,24,40,0.30);

  background: transparent; /* רקע האתר (סגול) של body נראה מאחור */
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, 'Helvetica Neue', Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  color: var(--text);
}
.photos-page  { --acc: #111111; --acc-soft: rgba(0, 0, 0, 0.03); }
.stories-page { --acc: #111111; --acc-soft: rgba(0, 0, 0, 0.036); }
.courses-page { --acc: #111111; --acc-soft: rgba(0, 0, 0, 0.03); }

/* --- ניצול רוחב המסך: פחות שוליים ריקים בצדדים --- */
/* פרופורציות אחידות בכל העמודים — כמו בעמוד התמונות (עמודי צד זהים ורוחב זהה) */
.articles-page .art-inner,
.offers-page .art-inner,
.questions-page .art-inner { max-width: 1560px; padding: 34px 26px 40px; }
.articles-page .art-layout,
.offers-page .art-layout,
.questions-page .art-layout { gap: 30px; }
@media (max-width: 1100px) {
  .articles-page .art-inner,
  .offers-page .art-inner,
  .questions-page .art-inner { padding: 24px 16px 36px; }
}

/* --- כותרות מקטע: פס אקסנט קצר במקום קו שחור עבה --- */
.articles-page .art-section-title {
  position: relative;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text);
  border-bottom: none;
  padding-bottom: 12px;
  margin-bottom: 18px;
}
.articles-page .art-section-title::after {
  content: "";
  position: absolute;
  bottom: 0;
  right: 0;
  width: 44px;
  height: 3px;
  border-radius: 99px;
  background: var(--acc);
}

/* --- שדה חיפוש --- */
.articles-page .art-search {
  padding: 14px 20px;
  border: 1px solid var(--line);
  border-radius: 14px;
  font-size: 15px;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.articles-page .art-search::placeholder { color: #9ca3af; }
.articles-page .art-search:focus {
  border-color: var(--acc);
  box-shadow: 0 0 0 4px var(--acc-soft);
}
.articles-page .art-search-wrap { margin-bottom: 22px; }

/* --- גריד מומלצים בראש העמוד --- */
.articles-page .art-featured-grid { gap: 16px; margin-bottom: 32px; }
.articles-page .art-featured-card {
  height: 220px;
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-md);
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.28s ease;
}
.articles-page .art-featured-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
}
.articles-page .art-featured-card img { transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1); }
.articles-page .art-featured-card:hover img { transform: scale(1.06); }
.articles-page .art-featured-info h3 { font-size: 15px; letter-spacing: -0.01em; }

/* --- כרטיסים בגריד (תמונות / סיפורים) --- */
.photos-page .art-row,
.stories-page .art-row {
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm);
  transition: transform 0.24s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.24s ease, border-color 0.24s ease;
}
.photos-page .art-row:hover,
.stories-page .art-row:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}
.photos-page .art-row-img-wrap img,
.stories-page .art-row-img-wrap img {
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}
.photos-page .art-row:hover .art-row-img-wrap img,
.stories-page .art-row:hover .art-row-img-wrap img { transform: scale(1.04); }
.photos-page .art-row-text h3,
.stories-page .art-row-text h3 { letter-spacing: -0.015em; line-height: 1.4; }
.photos-page .art-row-text p,
.stories-page .art-row-text p { color: var(--muted); font-size: 13px; }

/* --- רשימת שורות בעמוד הכתבות (נשאר רשימה, רק מרווח ונקי יותר) --- */
.articles-page:not(.photos-page):not(.stories-page) .art-rows {
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm);
}
.articles-page:not(.photos-page):not(.stories-page) .art-row { border-bottom-color: var(--line); }
.articles-page:not(.photos-page):not(.stories-page) .art-row-img-wrap { border-radius: var(--r-md); }

/* --- סרגל צד --- */
.articles-page .art-sidebar { gap: 14px; }
.articles-page .art-sidebar-box {
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm);
  padding: 18px;
}
.articles-page .art-sidebar-title {
  position: relative;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: -0.01em;
  border-bottom: 1px solid var(--line);
  padding-bottom: 12px;
  margin-bottom: 10px;
}
.articles-page .art-sidebar-title::after {
  content: "";
  position: absolute;
  bottom: -1px;
  right: 0;
  width: 32px;
  height: 2px;
  border-radius: 99px;
  background: var(--acc);
}
.articles-page .art-popular-item {
  border-bottom: 1px solid var(--line);
  border-radius: 8px;
  padding: 11px 8px;
  margin: 0 -8px;
  transition: background 0.18s ease, transform 0.18s ease;
}
.articles-page .art-popular-item:hover { background: var(--acc-soft); transform: translateX(-3px); }
.articles-page .art-popular-num {
  font-size: 20px;
  font-weight: 800;
  color: var(--acc);
  opacity: 0.28;
  min-width: 28px;
}

/* --- כפתורי פעולה --- */
.articles-page .art-add-btn {
  border: 1.5px dashed var(--line);
  background: rgba(255, 255, 255, 0.6);
  color: var(--muted);
  border-radius: var(--r-md);
  font-weight: 700;
  transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease;
}
.articles-page .art-add-btn:hover {
  background: var(--surface);
  border-color: var(--acc);
  color: var(--acc);
}
.articles-page .art-zoom-btn {
  border-radius: 8px;
  width: 28px;
  height: 28px;
  background: rgba(15, 17, 21, 0.55);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  opacity: 0;
  transition: opacity 0.2s ease, background 0.2s ease;
}
.articles-page .art-row:hover .art-zoom-btn,
.articles-page .art-featured-card:hover .art-zoom-btn,
.articles-page .art-zoom-btn:focus-visible { opacity: 1; }
/* התמונה היא position:relative עם z-index:1, ולכן כפתורים ממוקמים בלי
   z-index משלהם נצבעים מתחתיה ולא ניתנים ללחיצה. זו הסיבה שכפתור
   המחיקה לא עבד במצב עריכה בעוד כפתור הזום (z-index:10) כן עבד. */
.art-delete-btn,
.art-pin-btn { z-index: 10; }
.articles-page .art-delete-btn,
.articles-page .art-pin-btn { border-radius: 9px; backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); }

/* --- סרגל סינון: קו, ומתחתיו מין / גיל / מיקום שנפתחים במקום --- */
.photo-filter-section { margin-bottom: 18px; }
.photo-filter-rule {
  height: 1px;
  width: 100%;
  background: rgba(17, 17, 26, 0.14);
  margin: 4px 0 14px;
}
.photo-filter-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  overflow: visible;
}
.photo-filter-group {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}
.photo-filter-label {
  font-size: 11px;
  font-weight: 800;
  color: #9ca3af;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

/* הכפתורים הסגורים */
.photo-filter-trigger {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 15px;
  border: 1px solid var(--line, rgba(17,17,26,0.10));
  border-radius: 999px;
  background: #ffffff;
  color: #374151;
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.18s ease, color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}
.photo-filter-trigger:hover {
  transform: translateY(-1px);
  border-color: var(--acc, #111111);
  color: var(--acc, #262626);
  box-shadow: var(--shadow-sm);
}
.photo-filter-trigger.has-value {
  border-color: var(--acc, #111111);
  color: var(--acc, #262626);
}
.photo-filter-trigger-value {
  background: var(--acc, #111111);
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 9px;
  font-size: 11px;
  font-weight: 800;
}
.photo-filter-caret { font-size: 9px; opacity: 0.55; }
.photo-filter-clear {
  border: none;
  background: none;
  color: #9ca3af;
  font-family: inherit;
  font-size: 12px;
  font-weight: 700;
  text-decoration: underline;
  cursor: pointer;
  padding: 6px 4px;
}
.photo-filter-clear:hover { color: var(--acc, #262626); }

/* המצב הפתוח, שמחליף את שלושת הכפתורים */
.photo-filter-back {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border: 1px solid var(--line, rgba(17,17,26,0.10));
  border-radius: 50%;
  background: #ffffff;
  color: #6b7280;
  font-family: inherit;
  font-size: 13px;
  line-height: 1;
  cursor: pointer;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}
.photo-filter-back:hover {
  background: var(--acc, #111111);
  border-color: var(--acc, #111111);
  color: #ffffff;
}
.photo-tab-btn {
  padding: 7px 14px;
  border: 1px solid var(--line, rgba(17,17,26,0.10));
  border-radius: 999px;
  background: #ffffff;
  color: #4b5563;
  font-weight: 700;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}
.photo-tab-btn:hover {
  transform: translateY(-1px);
  border-color: var(--acc, #111111);
  color: var(--acc, #262626);
  box-shadow: var(--shadow-sm);
}
.photo-tab-btn.active {
  background: var(--acc, #111111);
  border-color: var(--acc, #111111);
  color: #ffffff;
}
.photo-tab-btn.active:hover { color: #262626; }
@media (max-width: 768px) {
  /* בטלפון הכל נשאר בשורה אחת ומתכווץ. במצב הפתוח האפשרויות לא
     נשברות לשורה שנייה, וגלילה אופקית היא רשת ביטחון למסך צר במיוחד. */
  .photo-filter-section { margin-bottom: 12px; }
  .photo-filter-rule { margin: 2px 0 10px; }
  .photo-filter-bar { gap: 6px; flex-wrap: nowrap; }
  .photo-filter-trigger { padding: 6px 11px; font-size: 11px; gap: 5px; flex-shrink: 0; }
  .photo-filter-trigger-value { font-size: 10px; padding: 1px 7px; }
  .photo-filter-group {
    flex-wrap: nowrap;
    overflow-x: auto;
    gap: 4px;
    padding-bottom: 1px;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }
  .photo-filter-group::-webkit-scrollbar { display: none; }
  .photo-tab-btn { padding: 5px 9px; font-size: 10px; flex-shrink: 0; }
  .photo-filter-label { font-size: 9px; flex-shrink: 0; }
  .photo-filter-back { width: 24px; height: 24px; font-size: 11px; }
}

/* --- עמוד פריט מלא --- */
.art-detail.articles-page { background: #ffffff; }
.art-detail-title { letter-spacing: -0.025em; font-size: 30px; line-height: 1.25; }
.art-detail-hero { border-radius: var(--r-lg, 16px); border-color: rgba(17,17,26,0.08); }
.art-detail-content p { font-size: 16px; line-height: 1.8; color: #374151; }
.art-detail-link { border-radius: 12px; padding: 13px 26px; transition: transform 0.18s ease, box-shadow 0.18s ease; }
.art-detail-link:hover { transform: translateY(-2px); box-shadow: 0 10px 24px -10px rgba(0, 0, 0, 0.5); }

/* --- מיקוד נגיש --- */
.articles-page a:focus-visible,
.articles-page button:focus-visible {
  outline: 2px solid var(--acc);
  outline-offset: 2px;
  border-radius: 6px;
}

/* --- פס גלילה דק --- */
.center-content { scrollbar-width: thin; scrollbar-color: rgba(17,17,26,0.22) transparent; }
.center-content::-webkit-scrollbar { width: 10px; }
.center-content::-webkit-scrollbar-track { background: transparent; }
.center-content::-webkit-scrollbar-thumb {
  background: rgba(17,17,26,0.18);
  border-radius: 99px;
  border: 3px solid transparent;
  background-clip: content-box;
}
.center-content::-webkit-scrollbar-thumb:hover { background: rgba(17,17,26,0.32); background-clip: content-box; }

@media (prefers-reduced-motion: reduce) {
  .articles-page *,
  .articles-page *::before,
  .articles-page *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
  .articles-page .art-row:hover,
  .articles-page .art-featured-card:hover { transform: none; }
}

@media (max-width: 768px) {
  .articles-page .art-section-title { font-size: 17px; }
  .articles-page .art-featured-card { height: 180px; }
  .art-detail-title { font-size: 24px; }
  .articles-page .art-zoom-btn { opacity: 1; }
}

/* ============================================================
   צפייה במסך מלא עם דפדוף (Gallery Lightbox)
   ============================================================ */
.art-lightbox {
  position: fixed;
  inset: 0;
  z-index: 1000000;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.92);
  -webkit-user-select: none;
  user-select: none;
  touch-action: pan-y;
}
.art-lb-img {
  max-width: 92vw;
  max-height: 88vh;
  object-fit: contain;
  border-radius: 8px;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.55);
}
.art-lb-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 52px;
  height: 52px;
  border: none;
  border-radius: 50%;
  background: rgba(38, 38, 38, 0.12);
  color: #262626;
  font-size: 30px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.18s ease;
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  direction: ltr;
}
.art-lb-nav:hover { background: rgba(38, 38, 38, 0.25); }
/* אתר RTL: הקודם מימין, הבא משמאל */
.art-lb-prev { right: 16px; }
.art-lb-next { left: 16px; }
.art-lb-close {
  position: absolute;
  top: 16px;
  left: 16px;
  width: 44px;
  height: 44px;
  border: none;
  border-radius: 50%;
  background: rgba(38, 38, 38, 0.12);
  color: #262626;
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.18s ease;
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
}
.art-lb-close:hover { background: rgba(38, 38, 38, 0.25); }
.art-lb-counter {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  color: #262626;
  font-size: 14px;
  font-weight: 700;
  background: rgba(0, 0, 0, 0.45);
  padding: 5px 14px;
  border-radius: 999px;
  letter-spacing: 0.5px;
  /* האתר RTL — בלי זה "1 / 4" מתהפך ל-"4 / 1" */
  direction: ltr;
  unicode-bidi: isolate;
}
@media (max-width: 768px) {
  .art-lb-img { max-width: 96vw; max-height: 82vh; }
  .art-lb-nav { width: 44px; height: 44px; font-size: 26px; }
  .art-lb-prev { right: 8px; }
  .art-lb-next { left: 8px; }
  .art-lb-close { top: 10px; left: 10px; width: 40px; height: 40px; }
  .art-lb-counter { bottom: 14px; }
}

/* בורר סוג הפרסום במודל הקהילה (שיתוף / סקר / שאלה) */
.comm-type-btn {
  border: 1.5px solid #e5e7eb;
  background: #ffffff;
  color: #6b7280;
  font-family: inherit;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}
.comm-type-btn:hover { border-color: #111111; color: #262626; }
.comm-type-btn.active {
  background: #111111;
  border-color: #111111;
  color: #ffffff;
}

/* ===== בקרות עמוד הסיפורים: בורר גודל + סינון קטגוריה ===== */
.stories-page .art-section-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.story-size-bar { display: flex; align-items: center; gap: 6px; }
.story-size-label { font-size: 12px; font-weight: 800; color: #9ca3af; }
.story-size-btn {
  width: 30px; height: 30px;
  border: 1px solid var(--line, rgba(17,17,26,0.1));
  background: #ffffff; color: #4b5563;
  border-radius: 8px; font-weight: 700; font-size: 13px;
  cursor: pointer; font-family: inherit;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease;
}
.story-size-btn:hover { border-color: var(--acc, #111111); color: var(--acc, #262626); }
.story-size-btn.active { background: var(--acc, #111111); border-color: var(--acc, #111111); color: #ffffff; }

.story-general-filter-bar { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }
.story-general-filter-btn {
  padding: 8px 16px; border: 1.5px solid #e2e8f0; border-radius: 999px;
  background: #ffffff; color: #475569; font-weight: 700; font-size: 14px;
  cursor: pointer; font-family: inherit; white-space: nowrap;
  transition: all 0.15s ease;
}
.story-general-filter-btn:hover { border-color: var(--acc, #111111); color: var(--acc, #262626); }
.story-general-filter-btn.active { background: var(--acc, #111111); color: #ffffff; border-color: var(--acc, #111111); }

.story-category-tabs {
  display: flex; flex-wrap: wrap; gap: 8px;
  margin: 14px 0 18px;
}
.story-cat-btn {
  padding: 7px 14px;
  border: 1px solid var(--line, rgba(17,17,26,0.1));
  border-radius: 999px;
  background: #ffffff; color: #4b5563;
  font-weight: 700; font-size: 13px;
  cursor: pointer; font-family: inherit; white-space: nowrap;
  transition: background 0.18s ease, color 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}
.story-cat-btn:hover { transform: translateY(-1px); border-color: var(--acc, #111111); color: var(--acc, #262626); }
.story-cat-btn.active { background: var(--acc, #111111); border-color: var(--acc, #111111); color: #ffffff; }

/* בחירת הגודל גוברת על ברירת המחדל הרספונסיבית, בכל רוחב מסך */
.stories-page.story-cols-2 .art-rows { grid-template-columns: repeat(2, 1fr) !important; }
.stories-page.story-cols-3 .art-rows { grid-template-columns: repeat(3, 1fr) !important; }
.stories-page.story-cols-4 .art-rows { grid-template-columns: repeat(4, 1fr) !important; }
@media (max-width: 768px) {
  .story-cat-btn { padding: 5px 11px; font-size: 11px; }
  .story-size-btn { width: 26px; height: 26px; font-size: 12px; }
}

/* ============================================================
   FINANCIAL CALCULATORS (LIGHT WHITE + ROSE PINK ACCENTS)
   ============================================================ */

.calc-page-wrapper {
  max-width: 1150px;
  margin: 0 auto;
  padding: 32px 20px;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  direction: rtl;
}

/* Header Hero Banner (Light Pink Glow) */
.calc-header-box {
  background: linear-gradient(135deg, #ffffff 0%, #f7f7f7 50%, #f5f5f5 100%);
  border: 1px solid #efefef;
  color: #1e293b;
  padding: 36px 40px;
  border-radius: 24px;
  margin-bottom: 32px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.04);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
  position: relative;
  overflow: hidden;
}

.calc-header-box::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0, 0, 0, 0.03) 0%, rgba(0, 0, 0, 0) 70%);
  pointer-events: none;
}

.calc-header-title h1 {
  margin: 0 0 10px 0;
  font-size: 32px;
  font-weight: 900;
  background: linear-gradient(90deg, #111111 0%, #111111 50%, #111111 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.5px; color: #ffffff; }

.calc-header-title p {
  margin: 0;
  color: #64748b;
  font-size: 15px;
  font-weight: 500;
}

.em-header-tag {
  background: rgba(0, 0, 0, 0.03);
  border: 1px solid #111111;
  color: #262626;
  padding: 10px 20px;
  border-radius: 50px;
  font-weight: 800;
  font-size: 14px;
}

/* Card Layout */
.calc-card-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  margin-bottom: 32px;
}

@media (max-width: 880px) {
  .calc-card-grid {
    grid-template-columns: 1fr;
  }
}

.calc-box {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  padding: 28px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.03);
  color: #0f172a;
}

.calc-form-group {
  margin-bottom: 22px;
}

.calc-form-group label {
  display: block;
  font-size: 13px;
  font-weight: 700;
  color: #475569;
  margin-bottom: 8px;
}

.calc-input-wrap input, .calc-input-wrap select, .em-stock-input, .em-input {
  width: 100%;
  padding: 13px 16px;
  border: 1.5px solid #cbd5e1;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 800;
  color: #0f172a;
  background: #f8fafc;
  outline: none;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-sizing: border-box;
}

.calc-input-wrap input:focus, .calc-input-wrap select:focus, .em-stock-input:focus, .em-input:focus {
  border-color: #111111;
  box-shadow: 0 0 0 4px rgba(0, 0, 0, 0.075);
  background: #ffffff;
}

.calc-kpi-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  margin-bottom: 24px;
}

.calc-kpi-card {
  background: #f8fafc;
  border-radius: 16px;
  padding: 20px 16px;
  text-align: center;
  border: 1px solid #e2e8f0;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.calc-kpi-card:hover {
  transform: translateY(-2px);
  border-color: #111111;
}

.calc-kpi-card.highlight {
  background: rgba(0, 0, 0, 0.024);
  border-color: #111111;
}

.calc-kpi-label {
  font-size: 12px;
  color: #64748b;
  font-weight: 700;
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.calc-kpi-val {
  font-size: 22px;
  font-weight: 900;
  color: #0f172a;
}

.calc-kpi-card.highlight .calc-kpi-val {
  color: #262626;
}

/* EVERYTHING MONEY MATRIX LIGHT TABLE */
.em-container {
  background: #ffffff;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.06);
  border: 1px solid #e2e8f0;
  color: #0f172a;
  margin-bottom: 36px;
}

.em-header-banner {
  background: linear-gradient(90deg, #111111 0%, #111111 50%, #111111 100%);
  color: #ffffff;
  padding: 18px 28px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 900;
  font-size: 15px;
  letter-spacing: 0.5px;
}

.em-stock-basics {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  margin-bottom: 28px;
}

.em-section-title {
  margin: 0 0 20px 0;
  color: #262626;
  font-size: 18px;
  font-weight: 900;
}

.em-stock-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 18px;
}

.em-stock-grid label {
  display: block;
  font-size: 12px;
  font-weight: 700;
  color: #64748b;
  margin-bottom: 6px;
}

.em-table-scroll {
  overflow-x: auto;
}

.em-table {
  width: 100%;
  border-collapse: collapse;
  text-align: center;
}

.em-table th {
  background: #f8fafc;
  color: #475569;
  padding: 16px 12px;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 1px;
  border-bottom: 2px solid #e2e8f0;
