/* בחירה יחידה (מיון / גודל) — עיגול רדיו גדול עם נקודה שחורה */
.pf-check input[type="radio"] {
  -webkit-appearance: none;
  appearance: none;
  width: 30px;
  height: 30px;
  margin: 0;
  border: 1.5px solid #9ca3af;
  border-radius: 50%;
  background: #ffffff;
  cursor: pointer;
  flex-shrink: 0;
  display: grid;
  place-content: center;
  transition: border-color .15s;
}
.pf-check input[type="radio"]::before {
  content: "";
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #111111;
  transform: scale(0);
  transition: transform .15s ease;
}
.pf-check input[type="radio"]:hover { border-color: #111111; }
.pf-check input[type="radio"]:hover:not(:checked)::before { background: #e5e7eb; transform: scale(0.55); }
.pf-check input[type="radio"]:checked { border: 2px solid #111111; }
.pf-check input[type="radio"]:checked::before { transform: scale(1); }
.pf-check-group .pf-check { padding: 11px 0; font-weight: 500; font-size: 16px; color: #111111; }
