.fb-composer-icons { display: flex; gap: 10px; font-size: 18px; }

/* --- פוסט --- */
.fb-post { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; margin-bottom: 16px; overflow: hidden; box-shadow: 0 1px 5px rgba(0, 0, 0, 0.05); }
.fb-post-head { display: flex; align-items: center; gap: 10px; padding: 12px 14px 8px; }
.fb-post-avatar { width: 42px; height: 42px; border-radius: 50%; overflow: hidden; background: #e2e8f0; display: flex; align-items: center; justify-content: center; font-size: 20px; cursor: pointer; flex-shrink: 0; }
.fb-post-avatar img { width: 100%; height: 100%; object-fit: cover; }
.fb-post-meta { flex: 1; min-width: 0; }
.fb-post-author { font-size: 15px; font-weight: 800; color: #0f172a; cursor: pointer; display: flex; align-items: center; gap: 4px; }
.fb-verified { background: #111111; color: #ffffff; border-radius: 50%; width: 16px; height: 16px; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; }
.fb-post-time { font-size: 12px; color: #64748b; }
.fb-post-text { padding: 4px 14px 10px; font-size: 15px; font-weight: 600; color: #0f172a; line-height: 1.5; }
.fb-post-sub { padding: 0 14px 10px; font-size: 13.5px; color: #475569; line-height: 1.5; }
.fb-post-img { width: 100%; background: #000000; cursor: pointer; max-height: 620px; overflow: hidden; }
.fb-post-img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.fb-post-stats { display: flex; gap: 14px; padding: 8px 14px; font-size: 13px; color: #64748b; border-bottom: 1px solid #f1f5f9; }
