/* ============================================================
   צופה סיפור עם עמודים (תמונה / טקסט מודגש)
   ============================================================ */
.story-viewer { margin-bottom: 24px; }
/* מסגרת אחידה בגובה קבוע לכל העמודים (תמונה/טקסט); טקסט ארוך נגלל בתוך המסגרת */
.story-frame { position: relative; }
.story-page-view {
  height: 480px;
  background: #fafafa;
  border: 1px solid #f0f0f0;
  border-radius: 14px;
  overflow-x: hidden;
  overflow-y: hidden;
  box-sizing: border-box;
  scrollbar-width: thin;
  scrollbar-color: #111111 #eef0f3;
}
/* פס גלילה קבוע — רק בעמוד טקסט (לא בתמונות) */
.story-page-view.story-view-text { overflow-y: scroll; }
/* פס גלילה קבוע וגלוי תמיד — כדי שהמשתמש ידע שאפשר לגלול */
.story-page-view::-webkit-scrollbar { width: 10px; }
.story-page-view::-webkit-scrollbar-track { background: #eef0f3; border-radius: 0 14px 14px 0; }
.story-page-view::-webkit-scrollbar-thumb { background: #111111; border-radius: 8px; border: 2px solid #eef0f3; color: #ffffff; }
/* רמז "גללו לעוד" בתחתית המסגרת */
.story-scroll-hint {
  position: absolute; left: 4px; right: 12px; bottom: 1px; height: 52px;
  display: flex; align-items: flex-end; justify-content: center;
  background: linear-gradient(to top, #fafafa 30%, rgba(250, 250, 250, 0));
  border-radius: 0 0 14px 14px; pointer-events: none;
}
.story-scroll-hint span {
  background: #111111; color: #ffffff; font-size: 11.5px; font-weight: 800;
  padding: 3px 12px; border-radius: 999px; margin-bottom: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.175); animation: shBounce 1.4s ease-in-out infinite;
}
@keyframes shBounce { 0%,100% { transform: translateY(0); } 50% { transform: translateY(3px); } }
.story-page-inner {
  min-height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 30px 26px;
  box-sizing: border-box;
}
.story-img-page { max-width: 100%; max-height: 420px; object-fit: contain; border-radius: 10px; cursor: zoom-in; display: block; }
/* עמוד תמונה בקורא הסיפורים — נפתח בגודל מלא, ברור וללא שוליים לבנים ענקיים */
.story-page-view.story-view-image {
  height: auto;
  min-height: auto;
  background: transparent;
  border: none;
}
.story-page-view.story-view-image .story-page-inner {
  padding: 0;
  width: 100%;
}
.story-page-view.story-view-image .story-img-page {
  width: 100%;
  max-width: 100%;
  max-height: 80vh;
  object-fit: contain;
  border-radius: 14px;
  display: block;
  margin: 0 auto;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
}
@media (max-width: 640px) {
  .story-page-view { height: 62vh; min-height: 320px; }
  .story-img-page { max-height: 56vh; }
  .story-page-view.story-view-image {
    height: auto;
    min-height: auto;
  }
  .story-page-view.story-view-image .story-img-page {
    width: 100%;
    max-height: 75vh;
    border-radius: 12px;
  }
}
.story-text-page {
  font-size: 15.5px;
  font-weight: 700;
  line-height: 1.75;
  color: #1e293b;
  text-align: center;
  width: 100%;
  max-width: 620px;
  margin: 0 auto;
  word-break: break-word;
  letter-spacing: 0.15px;
}
@media (max-width: 640px) { .story-text-page { font-size: 14px; line-height: 1.7; } }
.story-viewer-nav { display: flex; align-items: center; justify-content: center; gap: 12px; margin-top: 16px; direction: ltr; }
.story-nav-btn { width: 40px; height: 40px; border-radius: 50%; background: #111111; color: #ffffff; border: none; cursor: pointer; display: flex; align-items: center; justify-content: center; flex-shrink: 0; box-shadow: 0 2px 8px rgba(59,130,246,0.3); transition: background 0.15s; }
.story-nav-btn:hover { background: #111111; color: #ffffff; }
.story-nav-btn:disabled { opacity: 0.4; cursor: default; }
.story-page-thumbs { display: flex; gap: 8px; overflow-x: auto; padding: 4px; max-width: 100%; }
.story-page-thumb { width: 58px; height: 58px; border-radius: 8px; overflow: hidden; cursor: pointer; border: 2.5px solid #dddddd; flex-shrink: 0; background: #ffffff; transition: border-color 0.15s; }
.story-page-thumb.active { border-color: #111111; }
.story-thumb-text { width: 100%; height: 100%; font-size: 7px; font-weight: 700; color: #334155; padding: 4px; overflow: hidden; line-height: 1.25; direction: rtl; text-align: right; }
.story-page-counter { text-align: center; color: #94a3b8; font-size: 13px; font-weight: 700; margin-top: 8px; }








/* ============================================================
