.story-article-tags { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 30px; }
.story-article-tag { background: #f3f4f6; color: #374151; border-radius: 8px; padding: 8px 16px; font-size: 14px; font-weight: 600; }
.story-linked-chip { display: inline-flex; align-items: center; gap: 6px; background: linear-gradient(135deg,#f8f8f8,#efefef); color: #262626; border: 1px solid #ddd6fe; border-radius: 10px; padding: 10px 16px; font-size: 15px; font-weight: 700; cursor: pointer; margin: 4px auto 24px; transition: transform .15s, box-shadow .15s; }
.story-linked-chip:hover { transform: translateY(-2px); box-shadow: 0 6px 16px rgba(0, 0, 0, 0.09); }
.story-linked-chip b { font-weight: 800; }
