/* ============================================================
   וידג'ט העלאה מהירה לעמוד הבית (Quick Upload Hero Widget)
   ============================================================ */
.quick-upload-hero-container {
  margin: 0 0 28px;
  width: 100%;
  direction: rtl;
}

.qu-hero-card {
  position: relative;
  background: #ffffff;
  border-radius: 24px;
  border: 1px solid #e2e8f0;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.04), 0 1px 3px rgba(0, 0, 0, 0.02);
  padding: 36px 32px 32px;
  text-align: center;
  transition: all 0.3s ease;
}

.qu-back-btn {
  position: absolute;
  top: 24px;
  right: 24px;
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: all 0.2s;
}

.qu-back-btn:hover {
  background: #e2e8f0;
  color: #0f172a;
}

.qu-progress-dots {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  margin-bottom: 22px;
}

.qu-step-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #e2e8f0;
  transition: all 0.3s ease;
}

.qu-step-dot.active {
  width: 26px;
  border-radius: 12px;
  background: linear-gradient(135deg, #ffffff, #e7e7e7);
}

.qu-step-dot.done {
  background: #cbd5e1;
}

.qu-hero-title {
  font-size: 34px;
  font-weight: 900;
  color: #0f172a;
  letter-spacing: -0.03em;
  line-height: 1.25;
  margin-bottom: 8px;
}

.qu-gradient-text {
  background: linear-gradient(135deg, #ffffff 0%, #111111 60%, #111111 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  display: inline-block; color: #ffffff; }

.qu-hero-subtitle {
  font-size: 15px;
  color: #64748b;
  font-weight: 600;
  margin-bottom: 28px;
}

.qu-input-area {
  max-width: 680px;
  margin: 0 auto;
}

/* שלב 1: כפתורי בחירת יעד */
.qu-options-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;
  margin-bottom: 12px;
}
.qu-options-grid.is-single {
  grid-template-columns: minmax(0, 390px);
  justify-content: center;
}

.qu-dest-pill {
  background: #f8fafc;
  border: 1.5px solid #e2e8f0;
  border-radius: 16px;
  padding: 18px 14px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
}

.qu-dest-pill:hover {
  transform: translateY(-2px);
  border-color: #cbd5e1;
  background: #ffffff;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.04);
}

.qu-dest-pill.active {
  background: #ffffff;
  border-color: #e7e7e7;
  box-shadow: 0 0 0 3px rgba(229, 229, 229, 0.18), 0 8px 20px rgba(229, 229, 229, 0.1);
}

.qu-dest-pill .qu-pill-icon {
  font-size: 28px;
  line-height: 1;
}

.qu-dest-pill .qu-pill-text strong {
  display: block;
  font-size: 15px;
  font-weight: 800;
  color: #0f172a;
}

.qu-dest-pill .qu-pill-text small {
  font-size: 11.5px;
  color: #64748b;
  margin-top: 2px;
}

/* שורת קלט עם כפתור חץ למעלה */
.qu-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  background: #ffffff;
  border: 1.5px solid #cbd5e1;
  border-radius: 16px;
  padding: 6px 8px 6px 16px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.03);
  transition: all 0.25s ease;
}

.qu-input-wrapper:focus-within {
  border-color: #e7e7e7;
  box-shadow: 0 0 0 4px rgba(229, 229, 229, 0.15), 0 8px 25px rgba(0, 0, 0, 0.05);
}

.qu-text-input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 16px;
  font-weight: 600;
  color: #0f172a;
  background: transparent;
  font-family: inherit;
  padding: 10px 4px;
  direction: rtl;
}

.qu-text-input::placeholder {
  color: #94a3b8;
  font-weight: 400;
}

.qu-input-wrapper.is-textarea {
  flex-direction: column;
  align-items: stretch;
  padding: 14px;
}

.qu-textarea-input {
  width: 100%;
  border: none;
  outline: none;
  font-size: 15px;
  color: #0f172a;
  background: transparent;
  font-family: inherit;
  resize: vertical;
  min-height: 80px;
  direction: rtl;
}

.qu-textarea-input::placeholder {
  color: #94a3b8;
}

.qu-input-wrapper.is-textarea .qu-arrow-btn {
  align-self: flex-end;
  margin-top: 8px;
}

.qu-arrow-btn {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: linear-gradient(135deg, #ffffff 0%, #f5f5f5 100%);
  color: #262626;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
