/* ===================== CRM (עמוד המידע, למנהל) ===================== */
.crm {
  --crm-ink: #0f172a; --crm-ink2: #334155; --crm-muted: #64748b; --crm-line: #e2e8f0;
  --crm-surface: #ffffff; --crm-bg: #f8fafc; --crm-accent: #111111; --crm-accent-soft: #efefef;
  --crm-bar: #111111;
  max-width: 1100px; margin: 36px auto 0; padding: 0 0 40px; text-align: right; color: var(--crm-ink);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}
.crm-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 14px; padding-top: 24px; border-top: 2px solid var(--crm-line); }
.crm-title { margin: 0; font-size: 24px; font-weight: 900; }
.crm-sub { color: var(--crm-muted); font-size: 13.5px; margin-top: 2px; }
.crm-head-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.crm-btn { background: var(--crm-surface); border: 1px solid var(--crm-line); color: var(--crm-ink2); border-radius: 9px; padding: 8px 14px; font-size: 13px; font-weight: 800; cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; font-family: inherit; }
.crm-btn:hover { background: var(--crm-bg); }
.crm-btn-primary { background: var(--crm-accent); border-color: var(--crm-accent); color: #262626; }
.crm-btn-primary:hover { background: #111111; color: #ffffff; }
.crm-link { background: none; border: none; color: var(--crm-accent); font-weight: 700; cursor: pointer; padding: 0 4px; font-size: 12.5px; font-family: inherit; }
.crm-tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--crm-line); margin-bottom: 16px; overflow-x: auto; }
.crm-tab { background: none; border: none; border-bottom: 3px solid transparent; padding: 10px 14px; font-size: 14px; font-weight: 800; color: var(--crm-muted); cursor: pointer; white-space: nowrap; font-family: inherit; }
.crm-tab.active { color: var(--crm-accent); border-bottom-color: var(--crm-accent); }
.crm-empty { padding: 32px 16px; text-align: center; color: var(--crm-muted); font-size: 14px; }
.crm-muted { color: var(--crm-muted); font-size: 12.5px; }
.crm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin-bottom: 16px; }
.crm-kpi { background: var(--crm-surface); border: 1px solid var(--crm-line); border-radius: 12px; padding: 12px 14px; }
.crm-kpi-label { font-size: 12px; font-weight: 800; color: var(--crm-muted); }
.crm-kpi-value { font-size: 26px; font-weight: 900; color: var(--crm-ink); margin-top: 4px; font-variant-numeric: tabular-nums; }
.crm-kpi-sub { font-size: 11.5px; color: var(--crm-muted); margin-top: 2px; }
.crm-filters { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 8px; }
.crm-input { border: 1px solid #cbd5e1; border-radius: 8px; padding: 8px 10px; font-size: 13.5px; background: #ffffff; color: var(--crm-ink); font-family: inherit; box-sizing: border-box; }
.crm-filters input[type="search"] { flex: 1 1 220px; }
.crm-input-sm { width: 130px; padding: 6px 8px; font-size: 12.5px; }
.crm-count { font-size: 12.5px; color: var(--crm-muted); margin: 4px 0 8px; }
.crm-table-wrap { overflow-x: auto; border: 1px solid var(--crm-line); border-radius: 12px; background: var(--crm-surface); }
.crm-table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.crm-table th { text-align: right; font-size: 12px; color: var(--crm-muted); font-weight: 800; padding: 10px 12px; border-bottom: 1px solid var(--crm-line); background: var(--crm-bg); white-space: nowrap; }
.crm-table td { padding: 10px 12px; border-bottom: 1px solid #f1f5f9; vertical-align: middle; }
.crm-table tbody tr { cursor: pointer; }
