.crm-num { font-variant-numeric: tabular-nums; text-align: center !important; }
.crm-name { font-weight: 800; }
.crm-verified { color: #262626; font-weight: 900; }
.crm-badge { display: inline-block; padding: 2px 9px; border-radius: 999px; font-size: 11.5px; font-weight: 800; white-space: nowrap; }
.crm-tag { display: inline-flex; align-items: center; gap: 3px; background: var(--crm-accent-soft); color: #262626; border-radius: 6px; padding: 1px 7px; font-size: 11.5px; font-weight: 700; margin: 1px 0 1px 4px; }
