.crm-panel { background: var(--crm-surface); border: 1px solid var(--crm-line); border-radius: 14px; padding: 16px; margin-bottom: 14px; }
.crm-h3 { margin: 0 0 10px; font-size: 16px; font-weight: 900; }
.crm-h4 { margin: 16px 0 8px; font-size: 13.5px; font-weight: 900; color: var(--crm-ink2); }
.crm-note-line { margin: -4px 0 12px; }
.crm-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.crm-grid-2 > .crm-panel { margin-bottom: 14px; }
/* פסים אופקיים (משפך / הקלקות / יעדים) */
.crm-hbar { display: grid; grid-template-columns: 150px 1fr auto; align-items: center; gap: 10px; margin: 8px 0; font-size: 13px; }
.crm-hbar-label { font-weight: 700; color: var(--crm-ink2); }
.crm-hbar-track { height: 12px; background: #f1f5f9; border-radius: 4px; overflow: hidden; }
.crm-hbar-fill { height: 100%; background: var(--crm-bar); border-radius: 4px; }
.crm-hbar-val { font-weight: 800; font-variant-numeric: tabular-nums; white-space: nowrap; display: flex; align-items: baseline; gap: 6px; }
.crm-hbar-sub { font-weight: 600; font-size: 11.5px; color: var(--crm-muted); }
/* גרף עמודות */
.crm-chart-bars { display: flex; align-items: stretch; gap: 2px; height: 170px; direction: ltr; }
.crm-bar-col { flex: 1; display: flex; flex-direction: column; align-items: center; min-width: 0; outline: none; cursor: default; }
.crm-bar-val { font-size: 10.5px; font-weight: 800; color: var(--crm-ink2); height: 15px; white-space: nowrap; }
.crm-bar-area { flex: 1; width: 100%; display: flex; align-items: flex-end; justify-content: center; border-bottom: 1px solid var(--crm-line); }
.crm-bar { width: 72%; max-width: 38px; min-height: 2px; background: var(--crm-bar); border-radius: 4px 4px 0 0; }
.crm-bar-col:hover .crm-bar, .crm-bar-col:focus .crm-bar { background: #111111; color: #ffffff; }
.crm-bar.is-forecast { background: repeating-linear-gradient(45deg, #c4b5fd 0 4px, #efefef 4px 8px); border: 1.5px dashed var(--crm-bar); border-bottom: none; box-sizing: border-box; }
.crm-bar-label { font-size: 10.5px; color: var(--crm-muted); height: 16px; margin-top: 4px; white-space: nowrap; }
.crm-legend { display: flex; gap: 14px; justify-content: flex-start; margin-top: 8px; font-size: 12px; color: var(--crm-ink2); }
.crm-legend span { display: inline-flex; align-items: center; gap: 5px; }
.crm-sw { display: inline-block; width: 12px; height: 12px; border-radius: 3px; background: var(--crm-bar); }
.crm-sw.is-forecast { background: repeating-linear-gradient(45deg, #c4b5fd 0 3px, #efefef 3px 6px); border: 1px dashed var(--crm-bar); box-sizing: border-box; }
.crm-tip { position: fixed; z-index: 2147482000; background: #0f172a; color: #ffffff; font-size: 12.5px; font-weight: 700; padding: 6px 10px; border-radius: 8px; pointer-events: none; display: none; white-space: nowrap; direction: rtl; box-shadow: 0 6px 18px rgba(0, 0, 0, 0.25); }
/* לוח שלבים */
.crm-board { display: grid; grid-template-columns: repeat(5, minmax(150px, 1fr)); gap: 10px; overflow-x: auto; }
.crm-col { background: var(--crm-bg); border: 1px solid var(--crm-line); border-radius: 12px; padding: 10px; min-height: 120px; display: flex; flex-direction: column; gap: 6px; }
.crm-col-head { font-weight: 900; font-size: 13.5px; margin-bottom: 4px; display: flex; justify-content: space-between; align-items: center; gap: 6px; }
.crm-col-count { background: #ffffff; border: 1px solid var(--crm-line); border-radius: 999px; padding: 0 8px; font-size: 12px; color: var(--crm-ink2); }
.crm-col-card { background: #ffffff; border: 1px solid var(--crm-line); border-radius: 9px; padding: 8px 10px; text-align: right; cursor: pointer; display: flex; flex-direction: column; gap: 2px; font-family: inherit; font-size: 13px; }
.crm-col-card:hover { border-color: var(--crm-accent); }
.crm-col-empty { text-align: center; padding: 10px 0; }
/* משימות ואוטומציות */
.crm-switch { display: flex; align-items: center; gap: 8px; padding: 8px 0; font-size: 13.5px; cursor: pointer; border-bottom: 1px solid #f1f5f9; }
.crm-switch:last-child { border-bottom: none; }
.crm-switch input { width: 18px; height: 18px; accent-color: var(--crm-accent); }
.crm-task-list { display: flex; flex-direction: column; gap: 6px; }
.crm-task-wrap { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.crm-task { display: flex; flex-direction: column; gap: 2px; padding: 8px 10px; border: 1px solid var(--crm-line); border-radius: 9px; background: #ffffff; flex: 1; }
.crm-task label { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 13.5px; cursor: pointer; }
.crm-task input { accent-color: var(--crm-accent); width: 16px; height: 16px; }
.crm-task.done label span { text-decoration: line-through; color: var(--crm-muted); }
.crm-task.overdue { border-color: #fca5a5; background: #f5f5f5; }
.crm-task-add, .crm-note-add { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }
.crm-task-add .crm-input:first-child, .crm-note-add textarea { flex: 1 1 160px; }
.crm-notes { display: flex; flex-direction: column; gap: 6px; margin-top: 8px; }
.crm-note { background: #f8f8f8; border: 1px solid #e4e4e7; border-radius: 9px; padding: 8px 10px; font-size: 13.5px; white-space: pre-wrap; word-break: break-word; }
.crm-goal { margin: 10px 0 16px; }
.crm-goal-top { display: flex; justify-content: space-between; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 6px; }
.crm-inline { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 700; color: var(--crm-ink2); }
/* כרטיס לקוח */
.crm-modal { position: fixed; inset: 0; background: rgba(15, 23, 42, 0.55); z-index: 100010; display: none; align-items: flex-start; justify-content: center; padding: 24px 16px; overflow-y: auto; }
.crm-card { background: #ffffff; border-radius: 16px; width: 100%; max-width: 920px; padding: 20px; box-shadow: 0 24px 60px rgba(0, 0, 0, 0.3); text-align: right; color: var(--crm-ink, #0f172a); font-family: system-ui, -apple-system, 'Segoe UI', sans-serif; --crm-ink: #0f172a; --crm-ink2: #334155; --crm-muted: #64748b; --crm-line: #e2e8f0; --crm-bg: #f8fafc; --crm-accent: #111111; --crm-accent-soft: #efefef; }
.crm-card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.crm-card-name { font-size: 22px; font-weight: 900; }
.crm-card-badges { display: flex; align-items: center; gap: 8px; margin-top: 4px; }
.crm-x { background: #f1f5f9; border: none; border-radius: 50%; width: 34px; height: 34px; font-size: 15px; cursor: pointer; flex-shrink: 0; }
.crm-card-actions { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin: 12px 0 4px; padding-bottom: 12px; border-bottom: 1px solid var(--crm-line); }
.crm-card-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.crm-dl { display: grid; grid-template-columns: auto 1fr; gap: 5px 12px; margin: 0; font-size: 13.5px; }
.crm-dl dt { color: var(--crm-muted); font-weight: 700; }
.crm-dl dd { margin: 0; word-break: break-word; }
.crm-mini-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.crm-mini-stats div { background: var(--crm-bg); border: 1px solid var(--crm-line); border-radius: 9px; padding: 7px; text-align: center; display: flex; flex-direction: column; }
.crm-mini-stats b { font-size: 17px; font-variant-numeric: tabular-nums; }
.crm-mini-stats span { font-size: 11px; color: var(--crm-muted); }
.crm-tags-edit { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }
.crm-timeline { list-style: none; margin: 0; padding: 0; max-height: 620px; overflow-y: auto; }
.crm-timeline li { display: flex; gap: 10px; padding: 8px 0; border-bottom: 1px solid #f1f5f9; font-size: 13.5px; }
.crm-tl-dot { flex-shrink: 0; width: 10px; height: 10px; border-radius: 50%; margin-top: 5px; box-shadow: 0 0 0 3px #ffffff, 0 0 0 4px var(--crm-line); }
@media (max-width: 768px) {
  .crm-grid-2, .crm-card-grid { grid-template-columns: 1fr; }
  .crm-hide-sm { display: none; }
  .crm-hbar { grid-template-columns: 105px 1fr auto; font-size: 12px; }
  .crm-kpi-value { font-size: 22px; }
  .crm-card { padding: 16px; }
  .crm-chart-bars { height: 140px; }
  .crm-board { grid-template-columns: repeat(5, 160px); }
}

