/* ===== מכ"ם גולשים — מפה עגולה ברדיוס 10 ק"מ ===== */
html body .umap-box.radar-box { padding: 16px 14px 14px !important; border-radius: 22px !important; overflow: visible; }
.radar-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 12px; }
html body .radar-title { font-size: 16px; font-weight: 800; color: var(--dk-text, #262626) !important; }
html body .umap-count { font-size: 12px; font-weight: 700; color: #7ee0a6 !important; }
.radar-wrap { display: flex; flex-direction: column; align-items: center; gap: 8px; }
.radar-dial {
  position: relative; width: 100%; max-width: 236px; aspect-ratio: 1 / 1;
  border-radius: 50%;
  padding: 6px;
  background: #111111;
  border: 3px solid #f0f0f0;
  box-shadow: 0 6px 0 #f0f0f0; color: #ffffff; }
.radar-dial .umap-canvas {
  width: 100%; height: 100%;
  border-radius: 50%; overflow: hidden; position: relative; z-index: 0;
  direction: ltr;
  background: #7cc8f0;
  border: 3px solid #f0f0f0;
}
/* צבעים רוויים ובהירים בסגנון קרטון */
.radar-dial .radar-tiles { filter: saturate(2.1) contrast(1.15) brightness(1.04) hue-rotate(-6deg); }
.radar-dial .umap-canvas:not(.located) .radar-tiles { filter: saturate(1.2) brightness(.9); }
.radar-dial .leaflet-container { background: #7cc8f0; font-family: inherit; }
.radar-dial .leaflet-control-attribution {
  background: rgba(255, 255, 255, 0.75) !important; color: #2c2c2c !important;
  font-size: 8px !important; padding: 0 6px !important; border-radius: 6px;
  position: absolute; bottom: 14px; left: 50%; transform: translateX(-50%); margin: 0 !important; white-space: nowrap;
}
.radar-dial .leaflet-control-attribution a { color: inherit !important; }
.radar-ring-inner { stroke: #f0f0f0; stroke-opacity: .45; stroke-width: 2; stroke-dasharray: 6 6; }
.radar-north {
  position: absolute; z-index: 3; right: 6%; bottom: 6%;
  width: 30px; height: 30px; border-radius: 50%;
  display: grid; place-items: center;
  background: #8ff0b4; color: #2c2c2c; font-size: 14px; font-weight: 900;
  border: 3px solid #f0f0f0;
  box-shadow: 0 3px 0 #f0f0f0;
}
.radar-scale { font-size: 13px; font-weight: 900; letter-spacing: 2px; color: #111111; direction: ltr; }
/* אני — חץ לבן במרכז */
.radar-me { background: none; border: none; }
.radar-me svg { position: absolute; inset: 3px; width: 24px; height: 24px; fill: #ffffff; stroke: #f0f0f0; stroke-width: 2.4; stroke-linejoin: round; filter: drop-shadow(0 2px 0 #2c2c2c); }
.radar-me-pulse { display: none; }
/* גולשים בסביבה */
.umap-pin-wrap { background: none; border: none; }
.umap-pin {
  width: 26px; height: 26px; border-radius: 50%;
  background: var(--pink, #111111); color: #ffffff; border: 2.5px solid #f0f0f0;
  box-shadow: 0 3px 0 #f0f0f0;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 900; font-family: inherit;
}
.umap-pop { direction: rtl; text-align: right; font-size: 13px; line-height: 1.5; }
.umap-err { position: absolute; inset: 0; display: grid; place-items: center; padding: 20px; text-align: center; color: #818181; font-size: 12px; direction: rtl; }
.umap-actions { margin-top: 14px; display: flex; flex-direction: column; gap: 8px; }
.umap-row { display: flex; gap: 8px; }
html body .umap-btn {
  flex: 1; padding: 11px; border-radius: 12px; border: none;
  background: var(--pink-grad, linear-gradient(135deg, #111111, #111111)) !important; color: #ffffff !important;
  font-family: inherit; font-size: 13.5px; font-weight: 800; cursor: pointer;
}
html body .umap-btn[disabled] { opacity: .65; cursor: progress; }
html body .umap-btn.ghost { flex: 0 0 auto; background: rgba(38, 38, 38, 0.08) !important; color: var(--dk-text, #262626) !important; border: 1px solid rgba(38, 38, 38, 0.14); }
html body .umap-hint { font-size: 12px; color: var(--dk-muted, #a9a1c2) !important; text-align: center; line-height: 1.45; }
html body .umap-hint.small { font-size: 11px; }

/* ===== תגובות קוליות ===== */
.pc-actions { display: flex; gap: 8px; align-items: center; }
