/* ===================================================================
   תפריט נגישות (a11y.js) — כפתור צף + פאנל הגדרות
   =================================================================== */
:root { --page-zoom: 1; }
@media (min-width: 2000px) { :root { --page-zoom: 1.1; } }
@media (min-width: 2560px) { :root { --page-zoom: 1.2; } }

.a11y-root { --a11y-ink: #262626; --a11y-paper: #faf8ff; --a11y-line: #e4dcf7; --a11y-gold: #111111; direction: rtl; font-family: system-ui, -apple-system, 'Segoe UI', Arial, sans-serif; }
.a11y-launcher {
  position: fixed; bottom: 86px; left: 22px; z-index: 100001;
  width: 56px; height: 56px; border-radius: 50%;
  background: var(--a11y-ink); color: var(--a11y-gold);
  border: 4px solid #ffffff; box-shadow: 0 4px 16px rgba(0, 0, 0, 0.28);
  display: flex; align-items: center; justify-content: center; cursor: pointer; padding: 0;
  transition: transform .15s ease;
}
.a11y-launcher:hover { transform: scale(1.06); }
.a11y-launcher:focus-visible { outline: 3px solid var(--a11y-gold); outline-offset: 3px; }
.a11y-launcher.has-settings::after {
  content: ""; position: absolute; top: -2px; right: -2px; width: 14px; height: 14px;
  border-radius: 50%; background: #22c55e; border: 2px solid #ffffff;
}
.a11y-panel {
  position: fixed; bottom: 154px; left: 22px; z-index: 100002;
  width: 380px; max-width: calc(100vw - 32px); max-height: calc(100vh - 180px);
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--a11y-paper); color: var(--a11y-ink);
  border: 3px solid var(--a11y-ink); border-radius: 26px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.3);
}
.a11y-panel[hidden] { display: none; }
.a11y-head { display: flex; align-items: center; justify-content: space-between; background: var(--a11y-ink); color: #262626; padding: 18px 22px; }
.a11y-head h2 { margin: 0; font-size: 22px; font-weight: 800; }
.a11y-close { background: none; border: none; color: #262626; font-size: 22px; font-weight: 800; cursor: pointer; padding: 4px 8px; line-height: 1; }
.a11y-body { overflow-y: auto; padding: 4px 18px 18px; flex: 1; }
.a11y-body h3 { margin: 20px 2px 10px; font-size: 16px; font-weight: 800; color: #818181; }
.a11y-row {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  background: #ffffff; border: 2px solid var(--a11y-line); border-radius: 18px;
  padding: 10px 16px; margin-bottom: 10px;
}
.a11y-row-label { font-size: 16px; font-weight: 700; }
.a11y-stepper { display: flex; align-items: center; gap: 10px; }
.a11y-stepper .a11y-step-val { min-width: 52px; text-align: center; font-weight: 700; font-size: 15px; }
.a11y-step {
  width: 44px; height: 44px; border-radius: 50%; border: 2.5px solid var(--a11y-ink);
  background: var(--a11y-paper); color: var(--a11y-ink); font-size: 20px; font-weight: 700;
  cursor: pointer; display: flex; align-items: center; justify-content: center; padding: 0;
}
.a11y-step:hover { background: var(--a11y-ink); color: #262626; }
.a11y-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.a11y-tile {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px;
  min-height: 112px; padding: 14px 8px; background: #ffffff; color: var(--a11y-ink);
  border: 2px solid var(--a11y-line); border-radius: 18px; cursor: pointer;
  font-size: 15px; font-weight: 700; font-family: inherit;
  transition: border-color .15s, background .15s, color .15s;
}
.a11y-tile:hover { border-color: var(--a11y-ink); }
.a11y-tile.active { background: var(--a11y-ink); color: #262626; border-color: var(--a11y-ink); }
.a11y-root button:focus-visible { outline: 3px solid #111111; outline-offset: 2px; }
.a11y-foot { border-top: 2px solid var(--a11y-line); padding: 14px 18px 16px; background: var(--a11y-paper); }
.a11y-reset {
  width: 100%; padding: 15px; border: none; border-radius: 999px;
  background: var(--a11y-ink); color: #262626; font-size: 17px; font-weight: 800; cursor: pointer; font-family: inherit;
}
@media (max-width: 600px) {
  .a11y-launcher { width: 50px; height: 50px; left: 14px; bottom: 80px; }
  .a11y-panel { left: 16px; right: 16px; width: auto; bottom: 140px; max-height: calc(100vh - 160px); }
}

/* --- טקסט --- */
