}
.a11y-guide-bar, .a11y-mask-top, .a11y-mask-bottom { display: none; position: fixed; left: 0; right: 0; pointer-events: none; z-index: 100000; }
html.a11y-guide .a11y-guide-bar { display: block; height: 12px; background: rgba(250, 204, 21, 0.55); border-top: 2px solid #111111; border-bottom: 2px solid #111111; }
