html.a11y-mask .a11y-mask-bottom { display: block; bottom: 0; background: rgba(0, 0, 0, 0.6); }

/* --- תנועה ומדיה --- */
html.a11y-motion *, html.a11y-motion *::before, html.a11y-motion *::after { animation: none !important; transition: none !important; scroll-behavior: auto !important; }
html.a11y-images body :is(img, video, picture, iframe, svg image):not(.a11y-root *) { visibility: hidden !important; }
html.a11y-images body *:not(.a11y-root, .a11y-root *) { background-image: none !important; }

/* ===================================================================
   פוטר האתר — בתחתית כל עמוד
   =================================================================== */
.site-footer { background: rgba(10, 5, 26, 0.72); border-top: 1px solid #e4e4e7; color: #d8cff5; direction: rtl; margin-top: 40px; font-family: system-ui, -apple-system, 'Segoe UI', Arial, sans-serif; backdrop-filter: blur(8px); }
