  transition: transform .5s cubic-bezier(.2,.8,.2,1);
}
.home-feed-section .art-row:hover .art-row-img-wrap img { transform: scale(1.04); }

}
/* טקסט הכרטיס */
.home-feed-section .art-row-text { padding: 14px 16px 16px !important; }
.home-feed-section .art-row-text h3 { font-size: 16px !important; font-weight: 700 !important; color: #1d1d1f !important; margin: 0 0 6px !important; }
.home-feed-section .art-row-meta { font-size: 12px !important; color: #6e6e73 !important; }

/* כפתורי הכרטיס: משניים ורכים (לא שלושה גושים סגולים) */
.home-feed-page .home-feed-section .photo-card-links,
.home-feed-section .photo-card-links {
  flex-direction: row !important; flex-wrap: wrap !important; justify-content: flex-start !important; gap: 6px !important; margin-top: 12px !important;
}
.home-feed-page .home-feed-section .photo-card-links .art-telegram-btn,
.home-feed-page .home-feed-section .photo-card-links button:first-child,
.home-feed-section .photo-card-links .art-telegram-btn,
.home-feed-section .photo-card-links .art-save-btn {
  width: auto !important;
  background: rgba(38, 38, 38, 0.05) !important;
  color: #262626 !important;
  border: 1px solid rgba(38, 38, 38, 0.22) !important;
  border-radius: 999px !important;
  box-shadow: none !important;
  padding: 6px 12px !important;
  font-size: 12.5px !important;
  font-weight: 700 !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
}
.home-feed-page .home-feed-section .photo-card-links button:first-child svg,
.home-feed-section .photo-card-links .art-telegram-btn svg,
.home-feed-section .photo-card-links .art-save-btn svg { stroke: #ffffff !important; }
.home-feed-section .photo-card-links .art-telegram-btn:hover,
.home-feed-section .photo-card-links .art-save-btn:hover { background: rgba(38, 38, 38, 0.16) !important; border-color: rgba(255, 255, 255, 0.5) !important; color: #262626 !important; transform: none !important; }
.home-feed-section .photo-card-links .art-telegram-btn:hover svg,
.home-feed-section .photo-card-links .art-save-btn:hover svg { stroke: #ffffff !important; }
.home-feed-section .photo-card-links .art-save-btn.is-saved { background: rgba(16, 185, 129, 0.18) !important; border-color: rgba(16, 185, 129, 0.6) !important; color: #34d399 !important; }

/* רצועת ה-Hero: כרטיסים עגולים יותר על השחור */
.home-feed-page .qu-hero-wrap .qu-guide,
.home-feed-page .qu-hero-wrap .quick-upload-hero-container > * { border-radius: 28px !important; }

/* מובייל: הרצועות נוגעות בקצוות המסך */
@media (max-width: 768px) {
  #mainContent:has(> .home-feed-page) { padding-left: 0 !important; padding-right: 0 !important; }
  .home-feed-page .home-feed-section { padding: 40px 16px 44px !important; }
}

/* ===================================================================
   באנר פתיחה בעמוד הבית — רקע צהוב "נוזל" + שלושה כרטיסים מוטים
   =================================================================== */
.home-welcome {
  position: relative;
  overflow: hidden;
  background: #ffffff;
  min-height: 540px;
  display: flex;
  align-items: center;
}
.hw-drips { position: absolute; inset: 0; width: 100%; height: 100%; fill: #111111; z-index: 0; }
.hw-inner {
  position: relative; z-index: 1;
  width: 100%; max-width: 1180px; margin: 0 auto;
  padding: 56px 28px 70px;
  display: grid; grid-template-columns: 1fr 1.1fr; align-items: center; gap: 32px;
}
.hw-title {
  margin: 0 0 18px;
  font-size: clamp(40px, 6.2vw, 84px);
  line-height: 1.02; font-weight: 900; letter-spacing: -1.5px;
  color: #333333;
}
.hw-sub { margin: 0 0 30px; font-size: clamp(16px, 1.5vw, 19px); font-weight: 600; color: #623e54; line-height: 1.5; max-width: 460px; }
.hw-cta {
  border: none; cursor: pointer;
  background: #111111; color: #ffffff;
  font-size: 19px; font-weight: 800; font-family: inherit;
  padding: 15px 44px; border-radius: 999px;
  box-shadow: 0 10px 24px -10px rgba(0, 0, 0, 0.25);
  transition: transform 0.2s ease, background 0.2s ease;
}
.hw-cta:hover { background: #111111; transform: translateY(-2px); color: #ffffff; }

.hw-cards { position: relative; height: 400px; }
.hw-card {
  position: absolute; top: 20px;
  width: 42%; height: 340px; padding: 0; border: none; cursor: pointer;
  background: var(--tint); border-radius: 18px;
  display: flex; flex-direction: column; overflow: hidden;
  box-shadow: 0 24px 40px -18px rgba(242, 242, 242, 0.55);
  transition: transform 0.35s cubic-bezier(.2,.8,.2,1);
  font-family: inherit;
}
.hw-c1 { right: 0;   transform: rotate(7deg) translateY(16px); z-index: 1; }
.hw-c2 { right: 29%; transform: rotate(-2deg); z-index: 3; }
.hw-c3 { right: 58%; transform: rotate(-9deg) translateY(22px); z-index: 2; }
.hw-c1:hover { transform: rotate(4deg) translateY(0) scale(1.04); }
.hw-c2:hover { transform: rotate(0) translateY(-14px) scale(1.04); }
.hw-c3:hover { transform: rotate(-6deg) translateY(4px) scale(1.04); }
.hw-card-top {
  display: block; background: #ffffff; padding: 16px 12px 22px;
  border-radius: 0 0 50% 50% / 0 0 22px 22px;
}
.hw-card-brand { font-size: 20px; font-weight: 900; color: #333333; }
.hw-card-img { flex: 1; margin: 14px 14px 8px; border-radius: 14px; overflow: hidden; background: rgba(38, 38, 38, 0.25); display: flex; align-items: center; justify-content: center; }
.hw-card-icon { width: 46%; color: #333333; display: flex; }
.hw-card-icon svg { width: 100%; height: auto; }
.hw-c3 .hw-card-icon { color: #262626; }
.hw-card-img.hw-card-grid { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr; gap: 4px; padding: 4px; align-items: stretch; justify-items: stretch; }
.hw-card-grid img, .hw-card-grid i { width: 100%; height: 100%; min-height: 0; object-fit: cover; border-radius: 9px; display: block; }
.hw-card-grid i { background: rgba(38, 38, 38, 0.3); }
.hw-card-foot { display: block; padding: 0 12px 14px; font-size: 13px; font-weight: 800; color: #333333; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hw-c3 .hw-card-foot { color: #262626; }

@media (max-width: 860px) {
  .home-welcome { min-height: 0; }
  .hw-inner { grid-template-columns: 1fr; text-align: center; padding: 40px 16px 56px; gap: 18px; }
  .hw-sub { margin-left: auto; margin-right: auto; }
  .hw-cards { height: 290px; max-width: 420px; width: 100%; margin: 0 auto; }
  .hw-card { height: 240px; }
  .hw-card-brand { font-size: 15px; }
  /* מובייל: בכניסה לאתר רואים מיד את שלושת הכרטיסים — הכותרת והכפתור מתחתם */
  .hw-cards { order: -1; }
  .hw-inner { padding-top: 12px; }
}

/* ===================================================================
   עמוד גלריה — תצוגת "מוצר": תמונה גדולה במסגרת צבעונית + ריבועי בחירה
   =================================================================== */
.art-detail-inner:has(> .pd-show) { max-width: 1180px; }
.pshow {
  display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: center;
  max-width: 1140px; margin: 0 auto; text-align: right;
}
.pshow-stage { display: flex; flex-direction: column; align-items: center; gap: 22px; }
.pshow-frame,
.pshow-frame.photo-main-img-container {
  position: relative; overflow: visible; border: none; margin: 0; height: auto;
  width: 100%; aspect-ratio: 1 / 1.05;
  background: var(--tint, #b9b0e0);
  border-radius: 64px;
  display: flex; align-items: center; justify-content: center;
  padding: 7%; box-sizing: border-box; cursor: pointer;
  transition: background 0.4s ease;
}
.pshow-main {
  cursor: zoom-in;
  max-width: 100%; max-height: 100%; object-fit: contain; display: block;
  border-radius: 14px; box-shadow: 0 26px 40px -20px rgba(242, 242, 242, 0.6);
}
.pshow-main.pshow-in { animation: pshowIn 0.45s ease; }
@keyframes pshowIn { from { opacity: 0; transform: scale(0.96) translateY(8px); } to { opacity: 1; transform: none; } }
.pshow-dots { display: flex; gap: 10px; justify-content: center; min-height: 20px; }
.pshow-dot { width: 20px; height: 20px; border-radius: 50%; border: 2.5px solid #ffffff; background: transparent; padding: 0; cursor: pointer; }
.pshow-dot.active { background: #ffffff; }

.pshow-info { position: relative; }
.pshow-star { position: absolute; top: -10px; left: 0; font-size: 56px; line-height: 1; color: #111111; }
.pshow-title { margin: 0 0 22px; font-size: clamp(34px, 5vw, 68px); font-weight: 900; line-height: 1.05; color: #333333; letter-spacing: -1px; padding-left: 60px; }
.pshow-desc { margin: 0 0 14px; font-size: 18px; line-height: 1.6; color: #623e54; }
.pshow-desc:empty, .pshow-meta:empty { display: none; }
.pshow-meta { margin: 0 0 26px; font-size: 17px; font-weight: 700; color: #623e54; }
.pshow-tiles { display: grid; grid-template-columns: repeat(5, 1fr); gap: 18px 22px; margin-bottom: 30px; }
.pshow-tile {
  aspect-ratio: 1; border-radius: 22px; padding: 10%; border: 3px solid transparent;
  background: var(--tint); cursor: pointer; box-sizing: border-box; overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.pshow-tile img { width: 100%; height: 100%; object-fit: cover; border-radius: 8px; display: block; }
.pshow-tile:hover { transform: translateY(-3px); }
.pshow-tile.active { border-color: #ffffff; }
.pshow-line { height: 2px; background: #ffffff; margin-bottom: 40px; }
.pshow-cta {
  border: none; cursor: pointer; font-family: inherit;
  background: #111111; color: #ffffff; font-size: 20px; font-weight: 800;
  padding: 16px 64px; border-radius: 999px;
  transition: background 0.2s ease, transform 0.2s ease;
}
.pshow-cta:hover { background: #111111; transform: translateY(-2px); color: #ffffff; }

/* קומיקס בתוך המסגרת */
.comic-show .pshow-frame .story-page-view {
  width: 100% !important; height: 100% !important; min-height: 0 !important;
  background: transparent !important; border: none !important; border-radius: 0 !important;
  overflow: hidden !important; display: flex !important; align-items: center; justify-content: center;
}
.comic-show .pshow-frame .story-page-inner { padding: 0 !important; height: 100%; }
.comic-show .pshow-frame .story-img-page {
  max-width: 100% !important; max-height: 100% !important; object-fit: contain;
  border-radius: 14px !important; box-shadow: 0 26px 40px -20px rgba(242, 242, 242, 0.6);
  animation: pshowIn 0.45s ease;
}
.comic-show .pshow-tile.story-page-thumb { border-color: transparent !important; }
.comic-show .pshow-tile.story-page-thumb.active { border-color: #ffffff !important; }
.comic-show .pshow-tiles { max-height: 360px; overflow-y: auto; padding: 4px; }
.comic-show .story-comic-desc { white-space: pre-wrap; word-break: break-word; font-size: 18px; line-height: 1.6; color: #623e54; }

html.age-not-verified .pd-show.is-adult-album .pshow-tile img { filter: blur(25px) !important; }
html.age-not-verified .pshow-frame.photo-main-img-container.is-adult { filter: none !important; -webkit-filter: none !important; }

.pshow-arrow {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%; border: none; padding: 0;
  background: rgba(255, 255, 255, 0.92); color: #333333; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: 0 6px 16px -6px rgba(242, 242, 242, 0.5);
  opacity: 0; transition: opacity 0.2s ease;
}
.pshow-frame:hover .pshow-arrow { opacity: 1; }
.pshow-arrow.prev { left: 16px; }
.pshow-arrow.next { right: 16px; }
.pshow-desc p { font-size: 18px !important; color: #623e54 !important; margin: 0 0 10px !important; text-align: right !important; }
.pd-show-meta { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 0 0 28px; font-size: 15px; font-weight: 600; color: #623e54; }

@media (max-width: 860px) {
  .pshow { grid-template-columns: 1fr; gap: 28px; }
  .pshow-frame { border-radius: 40px; }
  .pshow-title { padding-left: 48px; }
  .pshow-star { font-size: 44px; }
  .pshow-tiles { grid-template-columns: repeat(4, 1fr); gap: 12px; }
  .pshow-tile { border-radius: 16px; }
  .pshow-line { margin-bottom: 26px; }
  .pshow-cta { width: 100%; padding: 15px; }
  .pshow-arrow { opacity: 1; width: 38px; height: 38px; }
  .pshow-desc p { font-size: 16px !important; }
}

/* ===================================================================
   רצועת ההעלאה בבית — כרטיסים בסגול כהה במקום לבן
   =================================================================== */
.home-feed-page .qu-hero-wrap .qu-hero-card,
.home-feed-page .qu-hero-wrap .qu-guide {
  background: #ffffff !important;
  border: 1px solid rgba(38, 38, 38, 0.08) !important;
  box-shadow: 0 24px 50px -24px rgba(0, 0, 0, 0.6) !important;
  color: #262626 !important;
}
.home-feed-page .qu-hero-wrap .qu-hero-title,
.home-feed-page .qu-hero-wrap .qu-guide-title,
.home-feed-page .qu-hero-wrap .qu-pill-text,
.home-feed-page .qu-hero-wrap .qu-pill-text *,
.home-feed-page .qu-hero-wrap .qu-detail-label,
.home-feed-page .qu-hero-wrap h1,
.home-feed-page .qu-hero-wrap h2,
.home-feed-page .qu-hero-wrap h3,
.home-feed-page .qu-hero-wrap h4,
.home-feed-page .qu-hero-wrap label { color: #262626 !important; }
.home-feed-page .qu-hero-wrap .qu-gradient-text {
  background: linear-gradient(90deg, #111111, #111111) !important;
  -webkit-background-clip: text !important; background-clip: text !important;
