.uw-head { display: flex; align-items: center; gap: 14px; margin-bottom: 18px; }
.uw-avatar { width: 58px; height: 58px; border-radius: 50%; flex-shrink: 0; display: grid; place-items: center; background: linear-gradient(135deg, #ff375f, #bf5af2); font-size: 26px; font-weight: 900; color: #ffffff; }
.uw-name { margin: 0; font-size: 36px; font-weight: 700; line-height: 1.05; color: #262626; letter-spacing: -0.5px; word-break: break-word; }
.uw-mid { display: flex; align-items: center; gap: 18px; margin-bottom: 16px; }
.uw-rings { width: 112px; height: 112px; flex-shrink: 0; }
.uw-lines { display: flex; flex-direction: column; gap: 6px; font-size: 24px; font-weight: 800; line-height: 1.05; font-variant-numeric: tabular-nums; }
.uw-lines small { font-size: 12.5px; font-weight: 700; margin-inline-start: 7px; opacity: .85; }
.uw-rate { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; padding: 10px 14px; border-radius: 20px; background: #1c1c1e; margin-bottom: 16px; }
.uw-stars { display: flex; gap: 2px; direction: ltr; }
.uw-star { background: none; border: none; padding: 0 2px; cursor: pointer; font-size: 27px; line-height: 1; color: #3a3a3c; transition: transform .12s ease, color .12s ease; }
.uw-star.on { color: #ffd60a; }
.uw-star:hover { transform: scale(1.18); color: #ffd60a; }
