.uw-none { color: #636366; font-weight: 600; }
.uw-text { color: #f2f2f7; }
.uw-link { background: none; border: none; padding: 0; font: inherit; color: #64d2ff; font-weight: 700; cursor: pointer; text-decoration: none; word-break: break-all; }
.uw-chips { display: flex; flex-wrap: wrap; gap: 6px; }
.uw-chip { padding: 4px 11px; border-radius: 999px; font-size: 13px; font-weight: 700; }
.uw-chip.like { background: rgba(48, 209, 88, 0.16); color: #30d158; }
.uw-chip.dislike { background: rgba(255, 69, 58, 0.16); color: #ff6961; }
@media (max-width: 520px) {
  .up-watch { border-radius: 52px; padding: 9px; }
  .up-watch-screen { border-radius: 44px; padding: 22px 18px 22px; }
  .uw-name { font-size: 28px; }
  .uw-rings { width: 88px; height: 88px; }
  .uw-lines { font-size: 20px; }
  .uw-label { width: 70px; font-size: 13px; }
}

/* שעון "מידע אישי" בבאנר: לחיץ, תגית בראש ובקשת התחברות לאורחים */
button.hw-watch { border: none; cursor: pointer; font: inherit; text-align: initial; transition: transform .25s ease; }
@media (min-width: 1800px) { button.hw-watch:hover { transform: translateY(-58%) rotate(0deg) scale(1.03); } }
.hw-watch-tag { font-size: 12px; font-weight: 800; padding: 3px 9px; border-radius: 999px; background: rgba(232, 255, 58, 0.14); color: #e8ff3a; direction: rtl; }
