.av-preview {
  width: 200px; height: 200px; border-radius: 50%;
  box-shadow: 0 0 0 6px rgba(38, 38, 38, 0.08), 0 20px 40px -16px rgba(0, 0, 0, 0.8);
}
.av-preview svg { width: 100%; height: 100%; display: block; }
.av-random { border: 1px solid rgba(38, 38, 38, 0.16); background: rgba(38, 38, 38, 0.07); color: #262626; border-radius: 999px; padding: 9px 18px; font: inherit; font-size: 14px; font-weight: 800; cursor: pointer; }
.av-right { flex: 1; min-width: 0; }
.av-tabs { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 16px; }
.av-tab { border: 1px solid rgba(38, 38, 38, 0.12); background: rgba(38, 38, 38, 0.05); color: #818181; border-radius: 999px; padding: 7px 13px; font: inherit; font-size: 13.5px; font-weight: 800; cursor: pointer; }
.av-tab.on { background: linear-gradient(135deg, #111111, #111111); border-color: transparent; color: #ffffff; }
.av-group { margin-bottom: 16px; }
.av-group-title { font-size: 13px; font-weight: 800; color: #111111; margin-bottom: 9px; }
.av-swatches { display: flex; flex-wrap: wrap; gap: 9px; }
.av-sw { width: 36px; height: 36px; border-radius: 50%; border: 3px solid transparent; background: var(--sw); cursor: pointer; box-shadow: 0 0 0 1px rgba(38, 38, 38, 0.2) inset; }
.av-sw.on { border-color: #ffffff; box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.25); }
.av-shapes { display: grid; grid-template-columns: repeat(auto-fill, minmax(70px, 1fr)); gap: 10px; }
.av-shape { aspect-ratio: 1; padding: 4px; border-radius: 18px; border: 2px solid rgba(38, 38, 38, 0.1); background: rgba(38, 38, 38, 0.04); cursor: pointer; }
.av-shape svg { width: 100%; height: 100%; display: block; }
.av-shape.on { border-color: #111111; background: rgba(0, 0, 0, 0.042); }
.av-actions { display: flex; gap: 10px; margin-top: 20px; }
.av-save { flex: 1; border: none; border-radius: 16px; padding: 14px; background: var(--warm-grad, linear-gradient(135deg, #111111, #111111)); color: #ffffff; font: inherit; font-size: 16px; font-weight: 900; cursor: pointer; }
.av-cancel { border: 1px solid rgba(38, 38, 38, 0.14); border-radius: 16px; padding: 14px 22px; background: rgba(38, 38, 38, 0.06); color: #262626; font: inherit; font-size: 15px; font-weight: 800; cursor: pointer; }
@media (max-width: 640px) {
