  .av-body { flex-direction: column; align-items: stretch; gap: 14px; }
  .av-preview { width: 140px; height: 140px; }
  .av-shapes { grid-template-columns: repeat(4, 1fr); }
}
.fr-av-btn { margin: 16px 0 0 !important; padding: 11px 20px !important; font-size: 15px !important; }

/* ===================================================================
   באנר עוגיות בסגול — קופץ מלמטה בכל כניסה
   =================================================================== */
.cookie-bar {
  position: fixed; z-index: 100002; left: 50%; bottom: 18px;
  transform: translate(-50%, 140%); opacity: 0;
  width: min(1100px, calc(100% - 32px)); box-sizing: border-box;
  display: flex; align-items: center; gap: 16px; flex-wrap: wrap; justify-content: center;
  padding: 14px 20px; border-radius: 22px;
  background: linear-gradient(135deg, #262626, #ffffff);
  border: 1px solid rgba(38, 38, 38, 0.14);
  box-shadow: 0 24px 50px -16px rgba(0, 0, 0, 0.75), 0 0 0 1px rgba(0, 0, 0, 0.075);
  color: #f1ecff; direction: rtl;
  transition: transform .5s cubic-bezier(.2,1.2,.3,1), opacity .35s ease;
}
.cookie-bar.show { transform: translate(-50%, 0); opacity: 1; }
.cookie-bar-icon { width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; background: rgba(255, 209, 102, 0.16); color: #111111; flex-shrink: 0; }
.cookie-bar-icon svg { width: 22px; height: 22px; }
.cookie-bar-text { margin: 0; flex: 1 1 320px; font-size: 15.5px; font-weight: 700; line-height: 1.5; }
.cookie-bar-btns { display: flex; gap: 8px; flex-wrap: wrap; }
.cookie-btn {
  border: 1px solid rgba(38, 38, 38, 0.18); border-radius: 12px;
  background: rgba(38, 38, 38, 0.08); color: #262626;
  padding: 10px 18px; font: inherit; font-size: 15px; font-weight: 800; cursor: pointer;
  transition: transform .12s ease, background .2s ease;
}
.cookie-btn:hover { transform: translateY(-1px); background: rgba(38, 38, 38, 0.14); }
.cookie-btn.yes { background: var(--pink-grad, linear-gradient(135deg, #111111, #111111)); border-color: transparent; color: #ffffff; }
.cookie-btn.ghost { background: transparent; color: #111111; border-color: rgba(255, 209, 102, 0.4); }
.cookie-policy {
  position: fixed; inset: 0; z-index: 100003; display: none; align-items: center; justify-content: center; padding: 16px;
  background: rgba(234, 234, 234, 0.72); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); direction: rtl;
}
.cookie-policy-card {
  position: relative; width: min(560px, 100%); max-height: 86vh; overflow: auto;
  background: linear-gradient(180deg, #f5f5f5, #ffffff); color: #e9e3ff;
  border: 1px solid rgba(38, 38, 38, 0.12); border-radius: 24px; padding: 26px 26px 22px;
}
.cookie-policy-card h2 { margin: 0 0 14px; font-size: 24px; font-weight: 900; color: #262626; }
.cookie-policy-card p { margin: 0 0 12px; font-size: 15px; line-height: 1.6; }
.cookie-policy-card b { color: #111111; }
.cookie-policy-note { color: rgba(233, 227, 255, 0.65); font-size: 13.5px !important; }
.cookie-policy-x { position: absolute; top: 16px; left: 16px; width: 34px; height: 34px; border-radius: 50%; border: none; background: rgba(38, 38, 38, 0.08); color: #262626; cursor: pointer; }
@media (max-width: 768px) {
  .cookie-bar { bottom: calc(92px + env(safe-area-inset-bottom, 0px)); padding: 14px; gap: 10px; border-radius: 18px; }
  .cookie-bar-icon { display: none; }
  .cookie-bar-text { font-size: 14px; flex-basis: 100%; text-align: center; }
  .cookie-bar-btns { width: 100%; }
  .cookie-btn { flex: 1; padding: 10px 8px; font-size: 14px; }
  .cookie-btn.ghost { flex-basis: 100%; }
  html.mtab-hidden .cookie-bar { bottom: calc(16px + env(safe-area-inset-bottom, 0px)); }
}

/* "חדש בקהילה": כפתור צהוב מלא בכל שלוש הכרטיסיות */
html body .home-trio .trio-cta {
  background: var(--warm-grad);
