.pshow-size-item b { font-size: 22px; font-weight: 900; color: #262626; font-variant-numeric: tabular-nums; }
.pshow-size-item b small { font-size: 12px; font-weight: 700; color: rgba(38, 38, 38, 0.6); margin-inline-start: 4px; }
