/* שורת "כל הגלריות": ממוצע אורך / היקף באתר */
.photo-size-avg { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: flex-end; direction: rtl; }
.psa-label { font-size: 13px; font-weight: 800; color: #111111; }
.psa-item {
  display: inline-flex; align-items: baseline; gap: 6px;
  padding: 5px 12px; border-radius: 999px;
  background: rgba(38, 38, 38, 0.07); border: 1px solid rgba(38, 38, 38, 0.12);
  font-size: 13px; font-weight: 700; color: rgba(38, 38, 38, 0.75);
}
.psa-item b { font-size: 16px; font-weight: 900; color: #262626; font-variant-numeric: tabular-nums; }
