.photo-size-avg { flex-wrap: nowrap; gap: 6px; }
.psa-item { white-space: nowrap; padding: 4px 10px; }

/* תג משתמש מאומת — חותם כחול עם וי */
.verified-seal {
  display: inline-flex; vertical-align: -0.2em; margin-inline-start: 4px; flex-shrink: 0;
  filter: drop-shadow(0 1px 2px rgba(29, 155, 240, 0.45));
}
.verified-seal svg { width: 100%; height: 100%; display: block; }
.photo-author-link .verified-seal { text-decoration: none; }

/* ===================================================================
   עמוד התמונות: ריבועי קטגוריות (תמונה + שם) מתחת לסרגל הסינון
   =================================================================== */
.pcat-tiles {
  display: grid; grid-auto-flow: column; grid-auto-columns: minmax(148px, 1fr);
  gap: 12px; margin: 4px 0 22px; padding: 2px 2px 8px;
  overflow-x: auto; scroll-snap-type: x proximity; scrollbar-width: thin;
  direction: rtl;
}
.pcat-tile {
  scroll-snap-align: start;
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  padding: 12px 10px 14px; border-radius: 18px; cursor: pointer;
  background: #ffffff; border: 1.5px solid rgba(38, 38, 38, 0.08);
  font: inherit; color: #262626; text-align: center;
  transition: transform .18s ease, border-color .18s ease, background .18s ease;
}
.pcat-tile:hover { transform: translateY(-3px); background: #f5f5f5; }
.pcat-tile.active { border-color: #111111; background: linear-gradient(180deg, rgba(0, 0, 0, 0.054), #ffffff); box-shadow: 0 10px 24px -14px rgba(0, 0, 0, 0.25); }
.pcat-img {
  width: 100%; aspect-ratio: 4 / 3; border-radius: 12px; overflow: hidden;
  display: grid; place-items: center;
  background: rgba(38, 38, 38, 0.05); color: rgba(38, 38, 38, 0.55);
}
.pcat-img img { width: 100%; height: 100%; object-fit: cover; display: block; }
.pcat-img svg { width: 38px; height: 38px; }
html.age-not-verified .pcat-img.is-adult img { filter: blur(14px); }
.pcat-name { font-size: 15px; font-weight: 800; line-height: 1.25; }
.pcat-count { font-size: 12px; font-weight: 700; color: rgba(38, 38, 38, 0.5); margin-top: -4px; }
.pcat-tile.edit { border-style: dashed; border-color: #111111; }
.pcat-tile.edit .pcat-img { color: #818181; }
@media (max-width: 640px) {
  .pcat-tiles { grid-auto-columns: 42%; gap: 10px; }
  .pcat-name { font-size: 14px; }
}
.pcat-tiles { grid-auto-columns: 158px; justify-content: start; }
@media (max-width: 640px) { .pcat-tiles { grid-auto-columns: 42%; } }

/* ===================================================================
   עמוד Blind Date
   =================================================================== */
.blinddate-page { direction: rtl; }
.bd-inner { max-width: 560px; margin: 0 auto; padding: 40px 16px 70px; }
.bd-card {
  background: linear-gradient(180deg, #f5f5f5, #ffffff);
  border: 1px solid rgba(38, 38, 38, 0.12); border-radius: 28px;
  box-shadow: 0 30px 60px -30px rgba(0, 0, 0, 0.85);
  color: #262626; text-align: center; padding: 34px 26px 28px;
}
.bd-logo {
  width: 72px; height: 72px; margin: 0 auto 14px; border-radius: 50%;
  display: grid; place-items: center; color: #ffffff;
  background: linear-gradient(135deg, #111111, #111111);
  box-shadow: 0 12px 30px -10px rgba(0, 0, 0, 0.25);
}
.bd-logo svg { width: 36px; height: 36px; }
.bd-card h1 { margin: 0 0 8px; font-size: 38px; font-weight: 900; color: #262626; letter-spacing: -0.5px; }
.bd-card h2 { margin: 18px 0 8px; font-size: 24px; font-weight: 900; color: #262626; }
.bd-card p { margin: 0 auto 22px; max-width: 420px; font-size: 16px; font-weight: 600; line-height: 1.6; color: rgba(38, 38, 38, 0.75); }
.bd-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 0; border-top: 1px solid rgba(38, 38, 38, 0.08); }
.bd-row > span { font-size: 16px; font-weight: 800; color: #111111; }
.bd-row > div { display: flex; gap: 8px; flex-wrap: wrap; justify-content: flex-end; }
.bd-chip { border: 1.5px solid rgba(38, 38, 38, 0.16); background: rgba(38, 38, 38, 0.06); color: #262626; border-radius: 999px; padding: 9px 18px; font: inherit; font-size: 15px; font-weight: 800; cursor: pointer; }
.bd-chip.on { background: var(--pink-grad, linear-gradient(135deg, #111111, #111111)); border-color: transparent; color: #ffffff; }
.bd-error { margin-top: 10px; color: #fca5a5; font-weight: 800; font-size: 14px; }
.bd-go {
  width: 100%; margin-top: 18px; padding: 16px; border: none; border-radius: 18px;
  background: var(--warm-grad, linear-gradient(135deg, #111111, #111111)); color: #ffffff;
  font: inherit; font-size: 18px; font-weight: 900; cursor: pointer;
}
.bd-note { display: block; margin-top: 12px; font-size: 12.5px; font-weight: 700; color: rgba(38, 38, 38, 0.5); }
.bd-ghost { border: 1px solid rgba(38, 38, 38, 0.18); background: rgba(38, 38, 38, 0.07); color: #262626; border-radius: 14px; padding: 11px 22px; font: inherit; font-size: 15px; font-weight: 800; cursor: pointer; }
.bd-ghost.small { padding: 8px 14px; font-size: 13.5px; margin-inline-start: auto; }
/* מכ"ם המתנה — טבעות מתרחבות סביב הלב */
.bd-radar { position: relative; width: 170px; height: 170px; margin: 6px auto 0; display: grid; place-items: center; }
.bd-radar > span { position: absolute; inset: 0; border-radius: 50%; border: 2px solid #111111; animation: bdPing 2.4s ease-out infinite; }
.bd-radar > span:nth-child(2) { animation-delay: .8s; }
.bd-radar > span:nth-child(3) { animation-delay: 1.6s; }
.bd-radar .bd-logo { margin: 0; position: relative; animation: bdBeat 1.2s ease-in-out infinite; }
@keyframes bdPing { from { transform: scale(.35); opacity: 1; } to { transform: scale(1); opacity: 0; } }
@keyframes bdBeat { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.08); } }
@media (prefers-reduced-motion: reduce) { .bd-radar > span, .bd-radar .bd-logo { animation: none; } }
/* צ'אט */
.bd-chat { padding: 0; overflow: hidden; text-align: right; display: flex; flex-direction: column; height: min(640px, 76vh); }
.bd-chat-head { display: flex; align-items: center; gap: 12px; padding: 14px 16px; border-bottom: 1px solid rgba(38, 38, 38, 0.08); background: rgba(38, 38, 38, 0.03); }
.bd-chat-head > div { display: flex; flex-direction: column; }
.bd-chat-head b { font-size: 17px; color: #262626; }
.bd-chat-head small { font-size: 12.5px; font-weight: 700; color: #7ee0a6; }
.bd-avatar { width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; background: linear-gradient(135deg, #111111, #111111); font-weight: 900; font-size: 18px; color: #ffffff; }
.bd-msgs { flex: 1; overflow-y: auto; padding: 16px; display: flex; flex-direction: column; gap: 8px; }
.bd-sys { align-self: center; padding: 5px 12px; border-radius: 999px; background: rgba(38, 38, 38, 0.06); font-size: 12.5px; font-weight: 700; color: rgba(38, 38, 38, 0.6); }
.bd-msg { display: flex; justify-content: flex-end; }
.bd-msg span { max-width: 78%; padding: 10px 14px; border-radius: 18px; border-bottom-left-radius: 6px; background: rgba(38, 38, 38, 0.09); color: #262626; font-size: 15.5px; line-height: 1.5; word-break: break-word; }
.bd-msg.mine { justify-content: flex-start; }
.bd-msg.mine span { background: var(--pink-grad, linear-gradient(135deg, #111111, #111111)); color: #ffffff; border-bottom-left-radius: 18px; border-bottom-right-radius: 6px; }
.bd-chat .bd-go { margin: 12px 16px 16px; width: auto; }
.bd-bar { display: flex; gap: 8px; padding: 12px; border-top: 1px solid rgba(38, 38, 38, 0.08); }
.bd-bar input { flex: 1; min-width: 0; height: 46px; padding: 0 16px; border-radius: 14px; border: 1px solid rgba(38, 38, 38, 0.14); background: rgba(38, 38, 38, 0.06); color: #262626; font: inherit; font-size: 15.5px; outline: none; }
.bd-bar input:focus { border-color: #111111; }
.bd-bar button { width: 46px; height: 46px; flex-shrink: 0; border: none; border-radius: 14px; background: var(--warm-grad, linear-gradient(135deg, #111111, #111111)); color: #ffffff; display: grid; place-items: center; cursor: pointer; }
.bd-bar button svg { width: 22px; height: 22px; }

/* פוטר: שורת אייקוני רשתות חברתיות */
.footer-social { display: flex; gap: 10px; margin-inline-start: auto; flex-wrap: wrap; }
.footer-social-btn {
  width: 40px; height: 40px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(38, 38, 38, 0.07); border: 1px solid rgba(38, 38, 38, 0.12);
  color: #262626 !important; text-decoration: none !important;
  transition: transform .15s ease, background .2s ease, color .2s ease;
}
.footer-social-btn svg { width: 19px; height: 19px; }
.footer-social-btn:hover { transform: translateY(-2px); background: var(--warm-grad, linear-gradient(135deg, #111111, #111111)); color: #ffffff !important; border-color: transparent; }
@media (max-width: 768px) {
  .footer-social { margin: 6px auto 0; justify-content: center; width: 100%; }
}
/* האייקונים בשורה משלהם, ממורכזים מעל שורת הזכויות (לא מוסתרים ע"י הכפתורים הצפים) */
.site-footer-bottom:has(.footer-social) { flex-wrap: wrap; }
.footer-social { order: -1; flex-basis: 100%; justify-content: center; margin: 0 0 14px !important; }


/* ===================================================================
   מובייל: סרגל טאבים תחתון — 6 כפתורים ברוחב שווה, סימטרי
   (תמונות · התאמות · בית · קהילות · נגישות · סגירה). בדסקטופ מוסתר.
   =================================================================== */
.mtabs, .mtab-open { display: none; }
@media (max-width: 768px) {
  html body .apple-nav .nav-links { display: none !important; }
  html body .apple-nav { backdrop-filter: none !important; -webkit-backdrop-filter: none !important; background: #ffffff !important; }
  .mtabs {
    position: fixed; z-index: 9500;
    left: 12px; right: 12px; margin: 0 auto; max-width: 460px;
    bottom: calc(12px + env(safe-area-inset-bottom, 0px));
    display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 2px;
    padding: 6px; border-radius: 999px;
    background: rgba(255, 255, 255, 0.86);
    -webkit-backdrop-filter: saturate(1.6) blur(18px); backdrop-filter: saturate(1.6) blur(18px);
    border: 1px solid rgba(38, 38, 38, 0.1);
    box-shadow: 0 14px 34px -10px rgba(0, 0, 0, 0.7);
    direction: rtl;
  }
  .mtab {
    height: 56px; min-width: 0;
    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
    border: none; border-radius: 999px; background: transparent; cursor: pointer;
    color: rgba(38, 38, 38, 0.7); font: inherit; font-size: 11.5px; font-weight: 700; line-height: 1;
    -webkit-tap-highlight-color: transparent;
    transition: background .2s ease, color .2s ease;
  }
  .mtab svg { width: 24px; height: 24px; flex-shrink: 0; }
  .mtab span { white-space: nowrap; }
  .mtab:active { background: rgba(38, 38, 38, 0.08); }
  .mtab.active { background: rgba(38, 38, 38, 0.13); color: #262626; }
  .mtab.active svg { color: #262626; }
  /* מקום לסרגל + כפתור הנגישות הצף מוסתר (פותחים מהסרגל) */
  html body { padding-bottom: calc(92px + env(safe-area-inset-bottom, 0px)) !important; }
  /* במובייל אין כפתור נגישות צף (לפי בקשה) */
  html body .a11y-launcher,
  html body .a11y-panel { display: none !important; }
  /* מצב מוסתר: הסרגל נעלם, כפתור הנגישות חוזר, וכפתור ☰ לפתיחה מחדש */
  html.mtab-hidden .mtabs { display: none; }
  html.mtab-hidden body { padding-bottom: 0 !important; }
  html.mtab-hidden .mtab-open {
    position: fixed; z-index: 9501; right: 14px; bottom: calc(80px + env(safe-area-inset-bottom, 0px));
    width: 50px; height: 50px; display: grid; place-items: center;
    border: 1px solid rgba(38, 38, 38, 0.14); border-radius: 50%;
    background: rgba(255, 255, 255, 0.9); color: #262626; cursor: pointer;
    -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
    box-shadow: 0 10px 26px -8px rgba(0, 0, 0, 0.7);
  }
