.td-card.behind { transform: scale(.94) translateY(14px); opacity: .7; z-index: 1; }
.td-card.fly.like, .td-card.fly.super { transform: translate(140%, -10%) rotate(22deg) !important; opacity: 0; }
.td-card.fly.nope { transform: translate(-140%, -10%) rotate(-22deg) !important; opacity: 0; }
.td-card.fly.super { transform: translate(0, -140%) !important; }
.td-photo { position: absolute; inset: 0; background-size: cover; background-position: center; }
html.age-not-verified .td-photo.is-adult { filter: blur(22px); transform: scale(1.1); }
.td-card::after { content: ""; position: absolute; inset: 45% 0 0; background: linear-gradient(to top, rgba(10,4,24,.95), rgba(10,4,24,0)); pointer-events: none; }
.td-info { position: absolute; z-index: 2; left: 0; right: 0; bottom: 0; padding: 18px 20px 20px; color: #262626; }
.td-name { font-size: 30px; font-weight: 900; line-height: 1.1; display: flex; align-items: center; gap: 4px; flex-wrap: wrap; }
