.td-meta { display: flex; gap: 12px; margin-top: 6px; font-size: 14.5px; font-weight: 700; color: rgba(38, 38, 38, 0.82); }
.td-more { position: absolute; left: 18px; bottom: 22px; width: 30px; height: 30px; border-radius: 50%; border: none; background: #ffffff; color: #333333; font: 900 16px/1 Georgia, serif; cursor: pointer; }
.td-stamp {
  position: absolute; z-index: 3; top: 34px; padding: 4px 12px; border-radius: 10px;
  border: 4px solid; font: 900 34px/1 system-ui, sans-serif; letter-spacing: 2px; pointer-events: none;
}
.td-stamp.like { left: 22px; color: #3de08a; border-color: #3de08a; transform: rotate(-16deg); opacity: var(--like); }
