.td-actions { display: flex; justify-content: center; align-items: center; gap: 14px; margin-top: 18px; direction: ltr; }
.td-btn {
  width: 56px; height: 56px; border-radius: 50%; display: grid; place-items: center; cursor: pointer;
  background: rgba(10, 4, 24, 0.6); border: 2px solid; transition: transform .15s ease, background .2s ease;
}
