.td-empty { position: absolute; inset: 0; border-radius: 24px; border: 2px dashed rgba(38, 38, 38, 0.14); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; text-align: center; color: #818181; padding: 20px; }
.td-empty-icon { width: 70px; height: 70px; border-radius: 50%; display: grid; place-items: center; background: rgba(0, 0, 0, 0.042); color: #262626; margin-bottom: 6px; }
