.td-reset { margin-top: 10px; border: none; border-radius: 999px; padding: 10px 20px; background: var(--warm-grad, linear-gradient(135deg,#111111,#111111)); color: #ffffff; font: inherit; font-weight: 900; cursor: pointer; }
.td-match { position: fixed; inset: 0; z-index: 100000; display: grid; place-items: center; padding: 20px; background: rgba(10, 4, 24, .82); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); direction: rtl; animation: authIn .35s ease; }
