.tg-search svg { width: 18px; height: 18px; flex: none; }
.tg-search input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; color: #262626; font: inherit; font-size: 16px; }
.tg-search input::placeholder { color: rgba(38, 38, 38, 0.42); }
.tg-search input::-webkit-search-cancel-button { display: none; }

.tg-guest {
  flex: none; margin: 0 16px 8px; padding: 10px 12px; border-radius: 14px; font-size: 13px; line-height: 1.45;
  background: rgba(0, 0, 0, 0.03); border: 1px solid #e4e4e7; color: rgba(38, 38, 38, 0.8);
