.tg-list { flex: 1; overflow-y: auto; overscroll-behavior: contain; padding-bottom: env(safe-area-inset-bottom, 0px); }
.tg-row { display: flex; align-items: center; gap: 12px; padding: 0 16px; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.tg-row:hover, .tg-row.active { background: rgba(38, 38, 38, 0.04); }
.tg-row:active { background: rgba(38, 38, 38, 0.07); }
.tg-avatar {
  width: 62px; height: 62px; flex: none; border-radius: 50%; display: grid; place-items: center;
