}
.tg-avatar-admin { background: linear-gradient(180deg, #f4f4f5, #111111); font-size: 28px; color: #ffffff; }
.tg-avatar-sm { width: 42px; height: 42px; font-size: 18px; }
.tg-row-main { flex: 1; min-width: 0; padding: 12px 0; border-bottom: 1px solid rgba(38, 38, 38, 0.08); align-self: stretch; display: flex; flex-direction: column; justify-content: center; gap: 3px; }
.tg-row:last-child .tg-row-main { border-bottom: 0; }
.tg-row-top { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.tg-row-name { font-size: 17px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tg-row-time { flex: none; font-size: 14px; color: rgba(38, 38, 38, 0.45); direction: ltr; }
.tg-row.unread .tg-row-time { color: #3e88f7; }
.tg-row-pin { flex: none; font-size: 13px; opacity: .6; }
.tg-verified { display: inline-grid; place-items: center; width: 17px; height: 17px; border-radius: 50%; background: #3e88f7; color: #ffffff; font-size: 11px; font-weight: 900; vertical-align: 1px; margin-inline-start: 4px; }
.tg-row-bottom { display: flex; align-items: center; gap: 8px; }
.tg-row-last {
  flex: 1; min-width: 0; font-size: 15px; line-height: 1.35; color: rgba(38, 38, 38, 0.5);
  display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;
}
.tg-row.unread .tg-row-last { color: rgba(38, 38, 38, 0.78); }
.tg-unread { flex: none; color: #3e88f7; font-size: 12px; }
.tg-empty { padding: 36px 24px; text-align: center; color: rgba(38, 38, 38, 0.45); font-size: 14px; line-height: 1.7; }

/* שיחה */
.tg-thread-head { border-bottom: 1px solid rgba(38, 38, 38, 0.06); background: rgba(255, 255, 255, 0.92); }
.tg-thread-who { flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: center; }
.tg-thread-who .tg-head-title { font-size: 17px; max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tg-thread-sub { font-size: 12.5px; color: rgba(38, 38, 38, 0.45); }
.tg-messages {
  flex: 1; overflow-y: auto; overscroll-behavior: contain; padding: 14px 12px;
  display: flex; flex-direction: column; gap: 4px;
  background: radial-gradient(120% 80% at 50% 0%, rgba(0, 0, 0, 0.03), transparent 60%), #ffffff;
}
.tg-day { align-self: center; margin: 8px 0; }
.tg-day span { font-size: 12.5px; font-weight: 600; padding: 4px 10px; border-radius: 999px; background: rgba(38, 38, 38, 0.08); color: rgba(38, 38, 38, 0.7); }
.tg-msg { display: flex; }
.tg-msg.mine { justify-content: flex-start; }
.tg-msg.theirs { justify-content: flex-end; }
.tg-bubble {
  max-width: 78%; padding: 7px 11px 6px; border-radius: 18px; font-size: 15.5px; line-height: 1.4;
  display: flex; flex-wrap: wrap; align-items: flex-end; gap: 4px 8px; word-break: break-word;
}
.tg-msg.mine .tg-bubble { background: linear-gradient(180deg, #111111, #111111); color: #ffffff; border-bottom-right-radius: 6px; }
.tg-msg.theirs .tg-bubble { background: #f0f0f0; color: #262626; border-bottom-left-radius: 6px; }
.tg-text { white-space: pre-wrap; }
.tg-msg-time { margin-inline-start: auto; font-size: 11px; color: rgba(38, 38, 38, 0.55); direction: ltr; }
.tg-compose {
  flex: none; display: flex; align-items: center; gap: 8px;
