}
.tg-compose input {
  flex: 1; min-width: 0; height: 42px; padding: 0 16px; border-radius: 999px; outline: 0;
  border: 1px solid rgba(38, 38, 38, 0.1); background: #ffffff; color: #262626; font: inherit; font-size: 16px;
}
.tg-send { width: 42px; height: 42px; flex: none; border: 0; border-radius: 50%; display: grid; place-items: center; cursor: pointer; background: #111111; color: #ffffff; }
