.pf-btn { height: 46px; padding: 0 26px; border-radius: 999px; font: inherit; font-size: 16px; font-weight: 800; cursor: pointer; display: inline-flex; align-items: center; justify-content: center; gap: 6px; transition: transform .12s ease, background .15s ease; }
.pf-btn:active { transform: scale(.97); }
