.pf-btn-outline { background: transparent; color: #262626; border: 2px solid #111111; }
.pf-btn-outline.following { border-color: rgba(38, 38, 38, 0.35); color: rgba(38, 38, 38, 0.85); }
.pf-btn-icon { width: 46px; padding: 0; background: transparent; color: #262626; border: 2px solid #111111; }
.pf-btn-icon svg { width: 22px; height: 22px; }
.pf-name { margin: 16px 0 0; font-size: 26px; font-weight: 800; line-height: 1.25; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.pf-handle { margin-top: 2px; color: #818181; font-size: 16px; text-align: right; }
.pf-bio { margin: 12px 0 0; font-size: 16.5px; line-height: 1.6; color: rgba(38, 38, 38, 0.88); white-space: pre-wrap; }
.pf-bio-add { margin-top: 10px; background: none; border: 1px dashed rgba(38, 38, 38, 0.3); color: rgba(38, 38, 38, 0.75); border-radius: 12px; padding: 8px 14px; font: inherit; cursor: pointer; }
