/* ===================================================================
   שורת כלים: # תגיות + סינון · גיליון (מסך מלא במובייל, חלון במחשב)
   =================================================================== */
.m-tools { display: flex; align-items: center; gap: 10px; margin: 4px 0 14px; direction: rtl; flex-wrap: wrap; --mt-bg: #ffffff; }
.m-tool {
  position: relative; width: 46px; height: 46px; border-radius: 14px; display: grid; place-items: center; cursor: pointer;
  background: rgba(38, 38, 38, 0.06); border: 1px solid rgba(38, 38, 38, 0.12); color: #262626;
}
.m-tool svg { width: 24px; height: 24px; }
.m-tool.on { border-color: #111111; color: #262626; }
.m-tool-badge { position: absolute; top: -6px; left: -6px; min-width: 19px; height: 19px; padding: 0 5px; border-radius: 999px; background: #111111; color: #ffffff; font-size: 11px; font-weight: 800; line-height: 19px; text-align: center; }
.m-tag-chip { display: inline-flex; align-items: center; gap: 8px; height: 36px; padding: 0 14px; border-radius: 999px; border: 0; cursor: pointer; background: rgba(0, 0, 0, 0.054); color: #262626; font: inherit; font-weight: 800; }
@media (min-width: 769px) { .m-tool-filter { display: none; } }

#m-sheet { position: fixed; inset: 0; z-index: 100002; display: none; direction: rtl; }
#m-sheet.show { display: block; }
html.ms-open { overflow: hidden; }
.ms-backdrop { position: absolute; inset: 0; background: rgba(38, 38, 38, 0.55); }
.ms-panel {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(520px, calc(100vw - 32px)); max-height: min(78vh, 720px);
  display: flex; flex-direction: column; background: #ffffff; color: #111111; border-radius: 18px; overflow: hidden; box-shadow: 0 30px 80px rgba(0, 0, 0, 0.5);
}
.ms-head { flex: none; display: flex; align-items: center; gap: 12px; height: 60px; padding: 0 14px; background: #111111; color: #ffffff; }
.ms-back { width: 40px; height: 40px; border: 0; background: none; color: #262626; cursor: pointer; display: grid; place-items: center; border-radius: 50%; }
.ms-back svg { width: 24px; height: 24px; }
.ms-title { font-size: 19px; font-weight: 800; letter-spacing: .3px; }
.ms-body { flex: 1; overflow-y: auto; padding: 8px 22px 24px; }
.ms-sec { padding-top: 18px; }
.ms-sec h4 { margin: 0 0 10px; font-size: 17px; font-weight: 800; color: #111111; }
.ms-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 18px; }
.ms-opt { display: flex; align-items: center; gap: 12px; min-height: 44px; cursor: pointer; color: #6b7280; font-size: 16.5px; -webkit-tap-highlight-color: transparent; }
.ms-opt input { position: absolute; opacity: 0; pointer-events: none; }
.ms-dot { width: 24px; height: 24px; flex: none; border-radius: 50%; background: #ececef; position: relative; transition: background .15s; }
.ms-opt.on { color: #111111; font-weight: 700; }
.ms-opt.on .ms-dot::after { content: ""; position: absolute; inset: 7px; border-radius: 50%; background: #111111; color: #ffffff; }
.ms-opt input:focus-visible + .ms-dot { box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.175); }
.ms-foot { flex: none; display: flex; gap: 10px; padding: 12px 16px calc(12px + env(safe-area-inset-bottom, 0px)); border-top: 1px solid #eeeeee; background: #ffffff; }
.ms-btn { flex: 1; height: 50px; border: 0; border-radius: 14px; cursor: pointer; font: inherit; font-size: 16px; font-weight: 800; color: #ffffff; background: linear-gradient(135deg, #111111, #111111); }
.ms-btn.ghost { flex: 0 0 auto; padding: 0 20px; background: #f1f1f4; color: #333333; }
.ms-tags { display: flex; flex-wrap: wrap; gap: 10px; padding-top: 16px; }
.ms-tag { display: inline-flex; align-items: center; gap: 8px; height: 42px; padding: 0 16px; border-radius: 999px; border: 1.5px solid #e5e5ea; background: #ffffff; color: #111111; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; }
.ms-tag b { font-size: 12.5px; color: #9ca3af; font-weight: 700; }
.ms-tag.on { border-color: #111111; background: #f5f0ff; color: #262626; }
.ms-empty { padding: 34px 10px; text-align: center; color: #6b7280; line-height: 1.8; font-size: 15.5px; }
@media (max-width: 768px) {
  .ms-backdrop { display: none; }
  .ms-panel { left: 0; top: 0; transform: none; width: 100%; height: 100%; max-height: none; border-radius: 0; }
  html.ms-open .mtabs, html.ms-open .mtab-open { display: none !important; }
}

/* עמוד הבית: ריבוע "העלאת תמונת גולשים" עם הכפתור הצהוב — במקום הריק בגריד הנתונים */
