.shop-card {
  position: relative; display: flex; align-items: center; gap: 12px; padding: 16px 14px; text-align: start; cursor: pointer;
  background: #ffffff; border: 1.5px solid rgba(38, 38, 38, 0.08); border-radius: 18px; color: #262626; font: inherit;
  transition: border-color .15s ease, background .15s ease, transform .12s ease; -webkit-tap-highlight-color: transparent;
}
.shop-card:hover { border-color: rgba(38, 38, 38, 0.22); }
.shop-card:active { transform: scale(.985); }
.shop-card.on { border-color: #111111; background: linear-gradient(180deg, rgba(0, 0, 0, 0.048), #ffffff); }
.shop-card:focus-visible { outline: 2px solid #111111; outline-offset: 2px; }
.shop-check { width: 26px; height: 26px; flex: none; border-radius: 8px; border: 2px solid rgba(38, 38, 38, 0.35); display: grid; place-items: center; color: transparent; transition: .15s; }
.shop-check svg { width: 16px; height: 16px; }
