.shop-ic.sm svg { width: 18px; height: 18px; }
.shop-txt { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.shop-txt b { font-size: 15.5px; font-weight: 800; }
.shop-txt small { font-size: 12.5px; color: rgba(38, 38, 38, 0.62); }
.shop-price { flex: none; font-size: 17px; font-weight: 900; color: #111111; font-variant-numeric: tabular-nums; }
.shop-bar {
  position: fixed; left: 50%; bottom: calc(18px + env(safe-area-inset-bottom, 0px)); transform: translate(-50%, 140%); z-index: 9400;
  width: min(560px, calc(100vw - 24px)); display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 10px 10px 10px 16px; border-radius: 20px; background: rgba(255, 255, 255, 0.94); border: 1px solid rgba(38, 38, 38, 0.12);
  -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px); box-shadow: 0 18px 40px -12px rgba(0, 0, 0, 0.7); transition: transform .25s cubic-bezier(.2, .8, .2, 1); direction: rtl;
}
.shop-bar.show { transform: translate(-50%, 0); }
.shop-bar-info { display: flex; flex-direction: column; padding-inline-start: 6px; }
.shop-bar-info b { font-size: 20px; font-weight: 900; color: #111111; }
.shop-bar-info span { font-size: 12.5px; color: rgba(38, 38, 38, 0.7); }
.shop-btn { height: 50px; padding: 0 22px; border: 0; border-radius: 14px; cursor: pointer; font: inherit; font-size: 16px; font-weight: 900; color: #ffffff; background: linear-gradient(135deg, #111111, #111111); box-shadow: 0 8px 20px -10px rgba(0, 0, 0, 0.25); display: inline-flex; align-items: center; gap: 8px; }
.shop-back { background: rgba(38, 38, 38, 0.08); border: 1px solid rgba(38, 38, 38, 0.12); color: #262626; border-radius: 999px; padding: 8px 16px; font: inherit; font-size: 13.5px; font-weight: 700; cursor: pointer; margin-bottom: 16px; }
.shop-co { display: grid; grid-template-columns: 1.1fr 1fr; gap: 14px; align-items: start; }
.shop-co-card { background: #ffffff; border: 1px solid rgba(38, 38, 38, 0.08); border-radius: 20px; padding: 18px; }
.shop-co-card h2 { margin: 0 0 12px; font-size: 18px; font-weight: 900; }
.shop-lines { list-style: none; margin: 0; padding: 0; }
