.shop-note { margin-top: 6px; font-size: 12.5px; color: rgba(38, 38, 38, 0.6); }
.shop-methods { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 14px; }
.shop-method { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 6px; border-radius: 14px; border: 1.5px solid rgba(38, 38, 38, 0.12); background: rgba(0, 0, 0, 0.1); color: #262626; font: inherit; font-size: 13px; font-weight: 700; cursor: pointer; }
