.shop-pay { width: 100%; justify-content: center; height: 54px; font-size: 17px; }
.shop-secure { display: flex; align-items: center; gap: 8px; margin-top: 12px; font-size: 12px; color: rgba(38, 38, 38, 0.6); line-height: 1.5; }
