@media (max-width: 768px) {
  .shop { padding: 18px 12px 170px; }
  .shop-grid { grid-template-columns: 1fr; gap: 10px; }
  .shop-card { padding: 14px 12px; }
  .shop-co { grid-template-columns: 1fr; }
  .shop-bar { bottom: calc(96px + env(safe-area-inset-bottom, 0px)); }
}
