/* ===== פורום: רשימת נושאים בסגנון פורום קלאסי ===== */
.fx-list { background: #ffffff; border: 1px solid #e6e6ec; border-radius: 12px; overflow: hidden; margin: 10px 0; }
.fx-bar { display: flex; justify-content: flex-end; align-items: center; padding: 8px 14px; background: #f7f7fa; border-bottom: 1px solid #e6e6ec; }
.fx-sort { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 600; color: #ec5f80; }
.fx-sort select { border: 0; background: transparent; font: inherit; color: inherit; cursor: pointer; }
.fx-row { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto 150px 170px; align-items: center; gap: 12px; padding: 12px 14px; border-bottom: 1px solid #efeff3; cursor: pointer; transition: background .12s ease; }
.fx-row:last-child { border-bottom: 0; }
.fx-row:hover { background: #fafafc; }
.fx-av .fo-avatar { width: 40px !important; height: 40px !important; font-size: 17px !important; }
.fx-av.sm .fo-avatar { width: 26px !important; height: 26px !important; font-size: 12px !important; }
.fx-main { min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.fx-title { font-size: 15px; font-weight: 600; color: #1d1d22; line-height: 1.3; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fx-row:hover .fx-title { color: #ec5f80; }
.fx-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 5px; font-size: 12.5px; color: #8a8f99; }
.fx-author { color: #6b7180; }
.fx-meta-m { display: none; }
.fx-pages { display: inline-flex; gap: 3px; margin-inline-start: 6px; }
.fx-pages button { min-width: 20px; height: 18px; padding: 0 4px; font: inherit; font-size: 11px; border: 1px solid #e3e3ea; border-radius: 4px; background: #ffffff; color: #6b7180; cursor: pointer; }
.fx-pages button:hover { border-color: #ec5f80; color: #ec5f80; }
.fx-stats { display: grid; grid-template-columns: auto auto; gap: 2px 14px; margin: 0; font-size: 13px; }
.fx-stats dt { color: #8a8f99; }
.fx-stats dd { margin: 0; text-align: left; color: #1d1d22; font-weight: 600; font-variant-numeric: tabular-nums; }
.fx-stats dd:nth-of-type(2) { font-weight: 400; color: #8a8f99; }
.fx-last { display: flex; align-items: center; justify-content: flex-end; gap: 10px; }
.fx-last-text { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; min-width: 0; }
.fx-last-t { font-size: 13px; color: #ec5f80; font-weight: 600; white-space: nowrap; }
.fx-last-n { font-size: 12px; color: #8a8f99; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 120px; }
.fx-row .fo-admin { display: inline-flex; gap: 4px; }
.fx-pager { display: flex; align-items: center; gap: 0; margin: 10px 0; }
.fx-pg { min-width: 34px; height: 32px; padding: 0 10px; border: 1px solid #e3e3ea; margin-inline-start: -1px; background: #ffffff; color: #ec5f80; font: inherit; font-size: 13.5px; font-weight: 600; cursor: pointer; }
.fx-pg:first-child { border-start-start-radius: 6px; border-end-start-radius: 6px; }
.fx-pg.on { background: #fff1f4; border-color: #ec5f80; color: #c43d60; position: relative; z-index: 1; }
.fx-pg.fx-next { margin-inline-start: 8px; border-radius: 6px; }
.fx-gap { min-width: 34px; height: 32px; display: inline-grid; place-items: center; border: 1px solid #e3e3ea; margin-inline-start: -1px; color: #8a8f99; background: #ffffff; }
html.theme-dark .fx-list { background: #111111 !important; border-color: #333336 !important; }
html.theme-dark .fx-bar { background: #1c1c1c !important; border-color: #333336 !important; }
html.theme-dark .fx-row { border-color: #2a2a2c !important; }
html.theme-dark .fx-row:hover { background: #1c1c1c !important; }
html.theme-dark .fx-title, html.theme-dark .fx-stats dd { color: #ececec !important; }
html.theme-dark .fx-pages button, html.theme-dark .fx-pg, html.theme-dark .fx-gap { background: #111111 !important; border-color: #333336 !important; }
