@media (max-width: 900px) {
  .fx-row { grid-template-columns: 40px minmax(0, 1fr) auto; gap: 10px; padding: 10px 12px; }
  .fx-stats, .fx-last { display: none; }
  .fx-meta-m { display: flex; }
  .fx-title { font-size: 13.5px; white-space: normal; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
  .fx-meta { font-size: 11px; gap: 4px; }
