/* קרוסלת תמונות בלי כיתוב */
.hc { position: relative; border-radius: 18px; overflow: hidden; margin: 0 0 14px; background: #ececf0; }
.hc-track { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; aspect-ratio: 16 / 9; }
.hc-track::-webkit-scrollbar { display: none; }
.hc-slide { flex: 0 0 100%; height: 100%; scroll-snap-align: start; border: 0; padding: 0; margin: 0; background: none; cursor: pointer; overflow: hidden; }
.hc-slide img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hc-slide.blur img { filter: blur(18px); transform: scale(1.1); }
.hc-arr { position: absolute; top: 50%; width: 40px; height: 40px; margin-top: -20px; border-radius: 50%; border: 0; background: rgba(255,255,255,.28); -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px); color: #ffffff; display: grid; place-items: center; cursor: pointer; }
.hc-arr svg { width: 22px; height: 22px; }
.hc-arr.prev { left: 10px; } .hc-arr.next { right: 10px; }
.hc-dots { position: absolute; bottom: 10px; left: 0; right: 0; display: flex; justify-content: center; gap: 6px; pointer-events: none; }
.hc-dots i { width: 7px; height: 7px; border-radius: 99px; background: rgba(255,255,255,.55); transition: width .2s ease, background .2s ease; }
.hc-dots i.on { width: 22px; background: #ffffff; }
