.hx-explore-row::-webkit-scrollbar { display: none; }
.hx-card { flex: 0 0 72%; max-width: 280px; scroll-snap-align: start; display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px; border-radius: 14px; border: 0; background: #ffffff; font: inherit; text-align: start; cursor: pointer; box-shadow: 0 1px 2px rgba(0,0,0,.04); }
