/* ===== פורומים — דף ראשי בסגנון פורום קלאסי (בהשראת הסולידית) ===== */
:root { --fi-acc: #b0244a; --fi-line: #e6e6ec; --fi-head: #f6f3f5; --fi-muted: #8a8f99; }
html.theme-dark { --fi-acc: #f27596; --fi-line: #333336; --fi-head: #232325; --fi-muted: #b0b3b8; }
.fi-layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; }
@media (min-width: 1100px) { .fi-layout { grid-template-columns: minmax(0, 1fr) 290px; align-items: start; } }
.fi-cat { background: #ffffff; border: 1px solid var(--fi-line); border-radius: 10px; overflow: hidden; margin: 0 0 16px; }
.fi-cat-title { margin: 0; padding: 10px 14px; font-size: 15px; font-weight: 700; color: var(--fi-acc); background: var(--fi-head); border-bottom: 1px solid var(--fi-line); }
.fi-row { display: grid; grid-template-columns: 40px minmax(0, 1fr) auto 76px 76px 230px; align-items: center; gap: 12px; padding: 12px 14px; border-bottom: 1px solid var(--fi-line); cursor: pointer; transition: background .12s ease; }
.fi-row:last-child { border-bottom: 0; }
.fi-row:hover { background: #fbf8fa; }
.fi-icon { color: var(--fi-acc); display: grid; place-items: center; }
.fi-icon svg { width: 30px; height: 26px; }
.fi-main { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.fi-title { font-size: 15px; font-weight: 700; color: var(--fi-acc); }
.fi-sub { font-size: 12.5px; color: var(--fi-muted); }
.fi-mstats, .fi-mlast { display: none; }
.fi-stat { display: flex; flex-direction: column; align-items: center; gap: 2px; }
.fi-stat small { font-size: 11.5px; color: var(--fi-muted); }
.fi-stat b { font-size: 14px; font-weight: 600; color: #1d1d22; font-variant-numeric: tabular-nums; }
.fi-last { display: flex; align-items: center; justify-content: flex-end; gap: 10px; min-width: 0; }
.fi-last-text { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; min-width: 0; }
.fi-last-title { font-size: 13px; color: var(--fi-acc); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 180px; }
.fi-last-title:hover { text-decoration: underline; }
.fi-last-text small, .fi-mlast small { font-size: 12px; color: var(--fi-muted); white-space: nowrap; }
.fi-name { color: var(--fi-acc); }
.fi-av .fo-avatar { width: 34px !important; height: 34px !important; font-size: 14px !important; }
.fi-none { font-size: 12px; color: var(--fi-muted); margin: 0; }
.fi-row .fo-admin { display: inline-flex; gap: 4px; }
/* סרגל צד: הודעות חדשות */
.fi-side-box { background: #ffffff; border: 1px solid var(--fi-line); border-radius: 10px; overflow: hidden; }
.fi-side-box h3 { margin: 0; padding: 10px 14px; font-size: 15px; font-weight: 700; color: var(--fi-acc); background: var(--fi-head); border-bottom: 1px solid var(--fi-line); }
.fi-new { display: flex; align-items: flex-start; gap: 10px; width: 100%; padding: 10px 14px; border: 0; border-bottom: 1px solid var(--fi-line); background: none; font: inherit; text-align: start; cursor: pointer; }
.fi-new:last-child { border-bottom: 0; }
.fi-new:hover { background: #fbf8fa; }
.fi-new .fi-av .fo-avatar { width: 30px !important; height: 30px !important; font-size: 12px !important; }
.fi-new-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.fi-new-text b { font-size: 13px; font-weight: 600; color: var(--fi-acc); line-height: 1.35; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.fi-new-text small { font-size: 11.5px; color: var(--fi-muted); }
html.theme-dark .fi-cat, html.theme-dark .fi-side-box { background: #111111 !important; }
html.theme-dark .fi-row:hover, html.theme-dark .fi-new:hover { background: #1c1c1c !important; }
html.theme-dark .fi-stat b { color: #ececec !important; }
@media (max-width: 1099px) { .fi-side { display: none; } }
/* מובייל: כמו בהשראה — אייקון בצד, כותרת, "נושאים: N הודעות: N", ההודעה האחרונה מתחת */
@media (max-width: 768px) {
  .fi-cat { border-radius: 0; border-left: 0; border-right: 0; margin: 0 0 10px; }
  .fi-row { grid-template-columns: minmax(0, 1fr) auto 36px; gap: 8px; padding: 12px 14px; }
  .fi-row .fi-icon { order: 9; }
  .fi-row :is(.fi-stat, .fi-last) { display: none; }
  .fi-main { gap: 3px; }
  .fi-title { font-size: 15.5px; }
  .fi-sub { display: none; }
  .fi-mstats { display: flex; gap: 10px; font-size: 12.5px; color: var(--fi-muted); }
  .fi-mstats b { color: #1d1d22; font-weight: 600; }
  html.theme-dark .fi-mstats b { color: #ececec; }
  .fi-mlast { display: flex; flex-direction: column; gap: 1px; }
  .fi-mlast .fi-last-title { max-width: 100%; font-size: 13px; }
  .fi-icon svg { width: 28px; height: 24px; }
}

