/* ===== הצעות: כרטיס בסגנון "שיחה נכנסת" — אווטאר, שם ושורת הצעה, כפתורים עגולים: אדום / כתום (משא ומתן) / ירוק ===== */
.ofp-list { display: flex; flex-direction: column; gap: 10px; }
.ofc { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 26px; background: #1c1c1e; color: #ffffff; }
.ofc.turn { box-shadow: 0 0 0 2px rgba(255,159,10,.55); }
.ofc-av { flex: none; width: 52px; height: 52px; border-radius: 50%; background: var(--av, #555); color: #ffffff; display: grid; place-items: center; font-size: 21px; font-weight: 800; cursor: pointer; }
.ofc-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; cursor: pointer; }
.ofc-name { font-size: 17px; font-weight: 700; color: #ffffff; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ofc-sub { font-size: 14px; color: #c9ccd1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ofc-st { font-size: 12px; color: #8e8e93; display: inline-flex; align-items: center; gap: 5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ofc-st i { width: 7px; height: 7px; border-radius: 50%; background: #8e8e93; flex: none; }
.ofc-st i.ok, .ofc-st i.accepted, .ofc-st i.signed { background: #34c759; }
.ofc-st i.no, .ofc-st i.rejected { background: #ff3b30; }
.ofc-st i.wait, .ofc-st i.counter, .ofc-st i.pending { background: #ff9f0a; }
.ofc-btns { flex: none; display: flex; gap: 8px; }
.ofc-b { width: 46px; height: 46px; border-radius: 50%; border: 0; display: grid; place-items: center; cursor: pointer; color: #ffffff; transition: transform .12s ease, filter .12s ease; }
.ofc-b svg { width: 22px; height: 22px; }
.ofc-b:hover { filter: brightness(1.08); }
.ofc-b:active { transform: scale(.92); }
.ofc-b.no { background: #e5352b; }
.ofc-b.deal { background: #ff9500; }
.ofc-b.ok { background: #34a853; }
.ofc-b.msg { background: #3a3a3c; }
@media (max-width: 420px) { .ofc-av { width: 44px; height: 44px; font-size: 18px; } .ofc-b { width: 40px; height: 40px; } .ofc-b svg { width: 19px; height: 19px; } .ofc-name { font-size: 15.5px; } }

/* דף הבית (מחשב): "את מי לעקוב" / "התחברות" — תיבה אחת עם שתי לשוניות */
