/* ===== מוצרים לזוגות — עמוד מוצר בסגנון חנות ===== */
.prd-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 6px 0 14px; }
.prd-head h1 { margin: 0; font-size: 24px; font-weight: 800; }
.prd { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.2fr) minmax(220px, .8fr); gap: 28px; align-items: start; }
.prd-gallery { display: flex; flex-direction: column; gap: 10px; }
