.prd-thumb { width: 64px; height: 64px; border-radius: 12px; border: 1.5px solid #e3e3ea; background: #f4f4f6; padding: 4px; cursor: pointer; display: grid; place-items: center; overflow: hidden; }
.prd-thumb.on { border-color: #2e8b57; box-shadow: 0 0 0 1px #2e8b57; }
