.prd-info { display: flex; flex-direction: column; gap: 8px; }
.prd-badge { align-self: flex-start; background: #f28c00; color: #fff; font-size: 12px; font-weight: 800; padding: 3px 10px; border-radius: 6px; }
.prd-title { margin: 0; font-size: 22px; font-weight: 800; line-height: 1.3; }
.prd-brand { font-size: 14px; color: #6b7180; }
.prd-brand b { color: #1d72f2; font-weight: 600; }
.prd-desc { margin: 4px 0 0; font-size: 15px; line-height: 1.6; color: #3a3f4a; }
