.prd-feats { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 12px 18px; }
.prd-feats li { display: flex; align-items: center; gap: 10px; font-size: 14.5px; }
.prd-feat-ic { flex: none; width: 36px; height: 36px; border-radius: 50%; background: #f1f1f4; display: grid; place-items: center; color: #2e8b57; }
.prd-feat-ic svg { width: 18px; height: 18px; }
.prd-buy { display: flex; flex-direction: column; gap: 12px; position: sticky; top: 70px; }
.prd-buy-box { border: 1px solid #e3e3ea; border-radius: 14px; padding: 18px; display: flex; flex-direction: column; gap: 14px; background: #ffffff; }
.prd-price { font-size: 28px; font-weight: 800; }
.prd-price.soft { font-size: 16px; color: #6b7180; font-weight: 600; }
.prd-cta { display: grid; place-items: center; height: 48px; border-radius: 10px; border: 0; background: #f28c00; color: #ffffff; font: inherit; font-size: 17px; font-weight: 800; text-decoration: none; cursor: pointer; }
.prd-cta:disabled { opacity: .55; cursor: default; }
.prd-wish { display: flex; align-items: center; justify-content: center; gap: 8px; height: 46px; border-radius: 10px; border: 1.5px solid #2e8b57; background: transparent; color: #2e8b57; font: inherit; font-size: 15px; font-weight: 700; cursor: pointer; }
.prd-wish svg { width: 20px; height: 20px; }
.prd-wish.on svg { fill: currentColor; }
