.prd-trust b { color: #2e8b57; font-size: 15px; }
.prd-more-h { margin: 28px 0 10px; font-size: 18px; font-weight: 800; }
.prd-more { display: flex; gap: 12px; overflow-x: auto; scrollbar-width: none; padding-bottom: 6px; }
.prd-more::-webkit-scrollbar { display: none; }
.prd-more-card { flex: 0 0 150px; display: flex; flex-direction: column; gap: 6px; padding: 10px; border: 1px solid #e3e3ea; border-radius: 14px; background: #ffffff; font: inherit; text-align: start; cursor: pointer; }
.prd-more-img { aspect-ratio: 1 / 1; border-radius: 10px; background: #f4f4f6; display: grid; place-items: center; overflow: hidden; }
.prd-more-img img { width: 100%; height: 100%; object-fit: cover; }
