.hw-site-st small { font-size: 11px; color: #8a8a90; }
@media (max-width: 768px) {
  html body:not(#_):not(#_):not(#_):not(#_):not(#_):not(#_) .hw-site { margin-top: 4px; padding-top: 6px; gap: 4px; }
