#adult-confirm .ac-badge { display: inline-grid; place-items: center; width: 48px; height: 48px; border-radius: 50%; background: #ec5f80; color: #fff; font-size: 16px; font-weight: 800; margin-bottom: 10px; }
#adult-confirm h3 { margin: 0 0 6px; font-size: 18px; }
#adult-confirm p { margin: 0 0 16px; font-size: 14px; line-height: 1.5; opacity: .8; }
#adult-confirm .ac-btns { display: flex; gap: 8px; }
#adult-confirm .ac-btns button { flex: 1; height: 44px; border-radius: 12px; border: 0; font: inherit; font-size: 14.5px; font-weight: 700; cursor: pointer; }
#adult-confirm .ac-no { background: rgba(127,127,127,.16); color: inherit; }
#adult-confirm .ac-yes { background: #ec5f80; color: #fff; }

